// Lot v3 of "Le Trésor des Taiseurs": the seven endings (act V) and the epilogue. Each ending is an entry sequence
// reached from VT_choix (lot v2): the way up from Sorne, the return to Salvèze, what becomes of the gold and of the
// Charter, and one final passage (end + epilogue) per ending: charte, republique, banque, silence, fortune, duc, noyade.
// Reads from lot v2 the gold brought up (set or: "remonte" for the three coffers, "partie" for what one can carry,
// flag vt:or_plomb when the bag was filled with gilded lead) and the salt crown (tresor:vt_couronne); both branches written.
var P = {};
// conditions this lot reads often (data only)
var PLEIN = { is: { or: "remonte" } }, PARTIE = { is: { or: "partie" } };
var OR = { any: [PLEIN, PARTIE] };
var PLOMB = { has: "vt:or_plomb" };
var VRAI = { all: [PLEIN, { not: PLOMB }] };
var CHARTE = { relic: "f_sorne" };
var LIBRE = { not: { any: [{ has: "lothaire:vaincu" }, { has: "lothaire:mort" }, { has: "lothaire:allie" }] } };
var CORNET = { item: "cornet" };
var SORNE = ["vn_anneau", "vn_bague_verrier", "vn_calice", "vn_coffre", "vn_couronne", "vn_peigne", "vn_perles", "vn_sceau", "vn_solde",
  "vt_bague", "vt_collier", "vt_ducats", "vt_jetons", "vt_sceptre"].map(function (t) { return { has: "tresor:" + t }; });
// the treasures found in Salvèze in the prologue and act I (one line of epilogue for them all)
var SALVEZE = ["pq_bague", "pq_plume", "pf_medaille", "ib_bourse", "ib_chevaliere", "ib_gobelet", "ib_sonneur", "ic_hanap", "ic_lingot",
  "ic_reconnaissance", "ig_anneau", "ig_broche", "ig_sceau", "ig_soie", "iq_bague", "iq_grenats", "if_denier", "if_gobelet", "if_perles"].map(function (t) { return { has: "tresor:" + t }; });
function END(id) { return { flag: "fin:" + id, quest: "V_sorne", ep: ["histoire", 3000] }; }

// ==================================================================== VF_noyade: the tide
Object.assign(P, {
  VF_noyade: { act: "V", title: "L'eau", place: "sorne",
    text: [
      "L'eau se referme sur toi, et le courant te prend d'un coup, comme une main posée à plat sur ton dos. Tu avales du sel. Tu remontes, tu cognes une poutre, tu retombes. Au-dessus de toi, la lumière fait une tache pâle qui bouge, puis une tache grise, puis plus rien.",
      { if: CHARTE, text: "La Charte est contre ta poitrine, dans son étui de cuir ciré, sanglée sous ta chemise. Elle tire vers le bas à chaque mouvement, ou c'est ta chemise, ou c'est l'eau qui entre dans le cuir." },
      { if: OR, text: "À ta ceinture, le sac de toile pèse de tout son or. Il t'a semblé léger dans la salle du trésor. Ici, il a le poids d'une ancre." },
      { with: "any", text: "Là-haut, quelqu'un crie ton nom. La voix arrive cassée par l'eau, puis l'eau la recouvre." },
      "Tu {{miroir#vf_noy_raison|voulais une dernière chose utile, pour Salvèze, pour les autres|voulais rester, parce qu'en bas, pour la première fois depuis la nuit des Lanternes, on te laissait enfin en paix}}.",
    ],
    choices: [
      { label: "Lâcher ce qui pèse et battre des jambes vers la lumière", to: "VF_noy_lacher" },
      { label: "Serrer contre toi ce que tu portes", to: "VF_noy_garder" },
      { label: "Frapper le diapason contre la pierre une dernière fois", hide: { not: { item: "diapason" } }, to: "VF_noy_voix" },
    ] },

  VF_noy_lacher: { act: "V", title: "Lâcher", place: "sorne",
    text: [
      "Tu défais la boucle de ta ceinture avec des doigts qui ne sentent plus rien. Ce que tu portais glisse le long de ta jambe et descend vers les pavés, sans hâte, en tournant sur lui-même. Tu te sens monter.",
      { if: OR, text: "Les pièces s'échappent du sac en descendant, une à une, et elles brillent chacune un instant dans l'eau noire avant de s'éteindre. Trois siècles d'or retournent à la rue où on l'a caché." },
      "Ta tête heurte de la pierre. Tu as monté sous un porche, ou sous une voûte, et la voûte te garde. Tes mains courent sur la pierre, trouvent une moulure, une arête, un creux. Dans le creux, il y a de l'air.",
    ],
    choices: [{ label: "Respirer", to: "VF_noy_air" }] },

  VF_noy_garder: { act: "V", title: "Garder", place: "sorne",
    text: [
      "Tu serres les bras sur ta poitrine. Tu coules. Le courant te tire par les chevilles le long d'une rue en pente, et les façades défilent, leurs fenêtres pleines d'algues qui te font signe toutes dans le même sens.",
      { if: CHARTE, text: "La Charte {{pie#vf_noy_charte|vaut une province, la moitié du delta, trois siècles de procès|vaut ce soir exactement ce que tu vaux, une ligne de cire et ton dernier souffle}}. Tu la tiens quand même." },
      { if: { all: [PLOMB, { not: CHARTE }] }, text: "L'or de ta besace {{pie#vf_noy_plomb|luit contre ta poitrine, lourd et jaune|est du plomb sous une feuille d'or, le premier appât des Taiseurs, et tu le serres comme un enfant}}." },
      { if: { all: [OR, { not: PLOMB }, { not: CHARTE }] }, text: "L'or {{pie|brille contre ta poitrine, lourd et franc|pèse onze livres, à peu près le poids d'un enfant de six ans endormi}}. Tu le tiens quand même." },
      { if: { not: { any: [OR, CHARTE] } }, text: "Tu n'as rien à serrer. Tes bras se ferment sur ta propre chemise." },
      "Une porte ouverte t'avale. Tu roules sur des marches, ton épaule cogne, ta main rencontre une rampe de fer. Tu t'y hisses, marche après marche, jusqu'à ce que ta bouche trouve de l'air sous une voûte.",
    ],
    choices: [{ label: "Respirer", to: "VF_noy_air" }] },

  VF_noy_voix: { act: "V", title: "La dernière note", place: "sorne",
    text: [
      "Tu frappes le diapason sur un seuil. Sous l'eau, la note s'étale au lieu de monter, lente, épaisse, et te rentre dans les os des bras.",
      "La rue autour de toi {{echo#vf_noy_echo|est noire et immobile, pleine d'une eau qui pousse|est pleine de cris d'il y a près de trois siècles, la nuit où la mer est entrée : « Les enfants sur les toits ! Les enfants d'abord ! » et une cloche, et une femme qui chante pour que les siens la trouvent dans le noir}}.",
      { after: "voile:vf_noy_echo", text: "Tu suis la voix qui chante. Elle te mène, dans le noir, jusqu'à une porte, une marche, une rampe, une voûte où il reste une poche d'air. Quelqu'un, cette nuit-là, a trouvé cette voûte avant toi." },
      { if: { not: { voile: "vf_noy_echo" } }, text: "Le courant te roule contre une porte, puis à travers. Une marche, une rampe. Ta bouche trouve de l'air sous une voûte." },
    ],
    choices: [{ label: "Respirer", to: "VF_noy_air" }] },

  VF_noy_air: { act: "V", title: "Sous la voûte", place: "sorne",
    text: [
      "Une main de largeur d'air entre l'eau et la pierre. Tu y colles la bouche et le nez, la tête renversée, et tu respires. L'air sent la chaux mouillée. L'eau monte d'un doigt pendant que tu comptes jusqu'à cent.",
      "Le noir est complet. Contre ta joue, la pierre de la voûte vibre doucement : au-dessus, quelque part, des gens marchent, crient, frappent.",
      { if: { has: "basse:taiseurs" }, text: "Au-dessus, une conque sonne, trois coups longs. Les Taiseurs appellent comme on appelle aux Joncs-Bas, les nuits de brume, pour les barques perdues." },
    ],
    choices: [
      { label: "Porter le cornet d'os à ton oreille, contre la pierre", hide: { not: CORNET }, to: "VF_noy_ecoute" },
      { label: "Chercher à tâtons une issue dans la voûte", to: "VF_noy_voute" },
    ] },

  VF_noy_ecoute: { act: "V", title: "Ce qu'on dit là-haut", place: "sorne",
    text: [
      "Tu poses le cornet entre ton oreille et la voûte. La pierre te porte les voix d'en haut, assourdies, très proches.",
      { with: "lison", text: "Lison. « {{oreille#vf_noy_lison|Remonte, imbécile, remonte|Je serais allée n'importe où avec toi, je ne te l'ai jamais dit, remonte}} », crie-t-elle, et sa voix se casse sur le dernier mot." },
      { with: "salome", text: "Salomé. « Donnez-moi la corde. {{oreille#vf_noy_salome|Je sais plonger, je descends la chercher|Pas deux fois, pas deux fois la même chose, je descends}}. » Quelqu'un la retient. Tu entends le bruit d'une lutte, puis Salomé qui jure." },
      { with: "tibere", text: "Tibère. « {{oreille|Il faut partir, les gars, l'eau monte|C'est moi qui aurais dû rester en bas, j'ai fini de servir à quelque chose}} », dit-il." },
      { with: "fauvette", text: "Fauvette se tait. Tu l'entends respirer très vite, tout près, comme si elle avait collé son oreille au même endroit que toi." },
      { with: "gildas", text: "Frère Gildas récite l'office des noyés, sans se presser, phrase après phrase. Sa voix reste égale." },
      { without: "any", text: "Ce sont des voix d'hommes que tu connais à peine, les gens de la barque. « {{oreille|On ne peut plus rien, on remonte|Je ne sais même pas son nom}} », dit l'un d'eux." },
    ],
    fx: { ep: ["perso", 500] },
    choices: [{ label: "Écouter jusqu'au bout", to: "VF_noy_fin" }] },

  VF_noy_voute: { act: "V", title: "La lucarne", place: "sorne",
    text: [
      "Tes doigts trouvent une arête, puis un vide : une lucarne, au sommet de la voûte, grande comme deux mains. De l'autre côté, de l'eau, et à travers l'eau, très loin, une lueur pâle qui doit être la lune.",
      "Tu y passes le bras jusqu'à l'épaule. Ton corps ne passera jamais.",
      { if: CHARTE, text: "L'étui de cuir, lui, passe. Tu le pousses dans la lucarne, puis de l'autre côté, et tu le lâches. Le cuir ciré est plus léger que l'eau : tu le sens monter contre tes doigts, puis partir.", else: "Tu laisses ta main dehors un moment, dans le courant, comme on la laisse dans celle de quelqu'un." },
    ],
    fx: { flag: "vf:charte_flotte" },
    choices: [{ label: "Reprendre ton souffle, une dernière fois", to: "VF_noy_fin" }] },

  VF_noy_fin: { act: "V", title: "La marée", place: "sorne", end: true, epilogue: true, fx: END("noyade"),
    text: [
      "L'air sous la voûte n'a plus que la hauteur d'un doigt. Tu y mets les lèvres. L'eau est moins froide qu'au début, ou c'est toi qui l'es davantage.",
      "Tu penses au quai des Lanternes, aux trois marches de la boutique, à la clochette au-dessus de la porte. Tu penses à Odeline qui compte la caisse, ses lunettes au bout du nez, et qui lève les yeux quand tu entres. Tu {{miroir#vf_noy_dernier|lui demandes pardon, et elle hausse les épaules comme elle le faisait toujours|lui dis enfin ce que tu as caché au Guet : que tu étais là ce soir-là, que tu as claqué la porte, et qu'elle a regardé la porte se fermer}}.",
      "La mer est sur Sorne, comme elle y est toutes les nuits de l'année sauf une, depuis près de trois siècles. Elle couvre la chaussée, les statues, le palais, la balise de chêne noir. Au soir, il ne reste que l'eau plate et grise jusqu'à l'horizon.",
      { with: "lison", text: "Lison reste à la proue jusqu'au soir, les bras croisés. Quand le soleil se couche, elle défait une de ses tresses, coupe une mèche avec son couteau et la donne à la mer." },
      { with: "salome", text: "Salomé se tait pendant tout le retour. Elle tient la barre. À Port-Vasier, elle fait graver un deuxième nom sur la planche de la chapelle des noyés, sous celui de Maïwenn." },
      { with: "tibere", text: "Tibère s'assied à l'arrière et sort ses dés de sa poche. Il les regarde longtemps, puis il les jette par-dessus bord, l'un après l'autre." },
      { with: "fauvette", text: "Fauvette garde ton manteau sur ses genoux jusqu'à Salvèze. Elle en a vidé les poches, par habitude, et elle a tout remis en place, une chose après l'autre." },
      { with: "gildas", text: "Frère Gildas dit la messe des morts sur le pont, à genoux, devant une mer vide. C'est la deuxième fois qu'il la dit pour quelqu'un de la boutique Carrus." },
      { if: { all: [{ has: "vf:charte_flotte" }, CHARTE] }, text: "Le lendemain, un pêcheur de Port-Vasier ramasse dans ses filets un étui de cuir ciré, gonflé d'eau, scellé de cire verte. Il le garde trois jours sur sa table sans l'ouvrir. Puis il le porte aux Joncs-Bas, parce que le sceau ressemble aux signes des dentellières." },
      { without: "any", text: "Les gens de la barque attendent jusqu'au soir, puis ils remontent l'ancre. Sur la balise de Sorne, le pêcheur de garde allume le feu de la cage pour une personne de plus." },
    ] },
});

// ==================================================================== VF_duc: Aveline's banners
var TIB = { with: "tibere", v: 10 }, FAU = { with: "fauvette", v: 10 }, LIS = { with: "lison", v: 10 }, SAL = { with: "salome", v: 10 }, GIL = { with: "gildas", v: 10 };
Object.assign(P, {
  VF_duc: { act: "V", title: "La fumée sur la Salve", place: null,
    fx: { ep: ["seance", 1500] },
    text: [
      "Vous quittez le pied de la tour de la Reine dans la matinée, dans le vent de terre, et la tour s'efface derrière vous dans la brume. Au milieu de l'après-midi, la côte des Hautes-Eaux sort de la brume, puis l'embouchure de la Salve, puis Salvèze. Au-dessus de la ville, une fumée grise monte droit dans l'air calme. Elle vient des faubourgs du nord.",
      { if: PLEIN, text: "Dans la cale, les trois coffres de la reine sont calés avec des sacs de lest et des voiles roulées. À chaque vague, le bois grince sous leur poids." },
      { if: PARTIE, text: "Dans la cale, sous une bâche, les besaces d'or que chacun a pu porter sont rangées contre la quille, et quelqu'un dort dessus." },
      { if: CHARTE, text: "La Charte est contre ta poitrine, dans son étui de cuir ciré. Tu y portes la main sans y penser, comme on vérifie sa bourse dans une foule." },
      "À l'entrée du chenal, une barque de pêcheurs vient à votre rencontre. L'homme qui rame a les yeux rouges. « Ils sont entrés à midi, dit-il. Par la porte des Sauniers. On a vu une fumée noire sur la mer, au matin, et une heure après les piques bleues étaient partout. {{oreille#vf_duc_pecheur|Il n'y a pas eu de combat, ou presque|Mon frère était de garde à la porte, et il a ouvert lui-même, pour vingt ducats et la vie de ses enfants}}. »",
      { if: { not: { has: "prevot:dejoue" } }, text: "« Le prévôt Delisle les attendait sous la voûte de la porte, ajoute-t-il, avec les clés de la ville sur un coussin de velours. Il a parlé le premier. »" },
      { if: { has: "prevot:dejoue" }, text: "« Le prévôt n'a rien ouvert, cette fois, ajoute-t-il, et ça n'a rien changé. Le Conseil a voté la reddition au milieu de la nuit, à six voix près, pour éviter l'assaut. Les émeutiers avaient brûlé les greniers du nord. Il n'y avait plus rien à défendre. »" },
      { with: "lison", text: "Lison regarde la fumée. « Les Joncs sont au sud, dit-elle. Le duc n'a rien à y prendre, à part nous. » Elle serre la barre." },
      { with: "tibere", text: "Tibère crache par-dessus bord. « Trente ans de Guet, dit-il. Trente ans à garder une porte qu'on ouvre avec un coussin. »" },
    ],
    choices: [
      { label: "Entrer au port aux Sauniers, sous les piques d'Aveline", to: "VF_duc_port" },
      { label: "Passer par les roseaux et attendre la nuit aux Joncs-Bas", if: { any: [{ present: "lison" }, { has: "basse:taiseurs" }, { has: "taiseurs:serment" }] }, why: "Il faut quelqu'un qui connaisse les passes des roseaux.", to: "VF_duc_joncs" },
    ] },

  VF_duc_port: { act: "V", title: "La chaîne du port", place: "port",
    text: [
      "Le port aux Sauniers est fermé par la grande chaîne, tendue entre les deux tours. Une barque d'Aveline vous accoste, quatre piquiers et un sergent à cuirasse bleue, qui saute à bord sans demander. « Inspection, dit-il dans un salvézan sans accent. Ordre du gouverneur. Ce que vous portez, d'où vous venez, où vous allez. »",
      "Il soulève une bâche du bout de sa pique. Ses yeux passent sur toi, sur tes compagnons, sur la cale. « {{oreille#vf_duc_sergent|Je fais mon travail, rien de plus|Je suis né rue des Tanneurs, ma mère y vit encore, et si on me voit fermer les yeux elle sera pendue avec moi}}. »",
      { if: OR, text: "Sous la bâche, il y a l'or que tu rapportes de Sorne. La toile est encore baissée. Il a la main dessus." },
      { with: "fauvette", text: "Fauvette s'est assise sur un tas de filets, l'air de s'ennuyer à mourir. Ses yeux comptent les piquiers, puis les nœuds qui tiennent la bâche." },
    ],
    choices: [
      { label: "Lui parler tout bas de sa mère, rue des Tanneurs", hide: { not: { voile: "vf_duc_sergent" } }, fx: { ep: ["perso", 800], flag: "vf:sergent_tanneurs" }, to: "VF_duc_ville" },
      { label: "Lui glisser dix ducats dans le gant", if: { gold: { min: 200 } }, why: "Il te faut dix ducats.", fx: { gold: -200 }, to: "VF_duc_ville" },
      { label: "Faire disparaître ce qui compte sous les filets", who: "fauvette", test: { dom: "discretion", diff: -10, label: "Cacher la cargaison", help: [FAU] },
        win: { to: "VF_duc_ville" }, lose: { to: "VF_duc_fouille" } },
      { label: "Lui raconter que vous rentrez de la pêche aux épaves de Port-Vasier", test: { dom: "social", diff: -20, label: "Mentir au sergent", help: [SAL, TIB] },
        win: { to: "VF_duc_ville" }, lose: { to: "VF_duc_fouille" } },
      { label: "Jeter les piquiers à l'eau", fight: { title: "La chaîne du port", enemies: [{ id: "soldat_aveline", n: 3 }],
        win: { fx: { flag: "vf:port_force" }, to: "VF_duc_ville" }, lose: { to: "VF_duc_fouille" },
        flee: { label: "Sauter sur le quai et filer dans les ruelles", dom: "discretion", diff: -10, to: "VF_duc_fouille" } } },
    ] },

  VF_duc_fouille: { act: "V", title: "La fouille", place: "port",
    text: [
      "On vous fait mettre à genoux sur le quai, les mains sur la nuque. Les piquiers vident la barque sur les pavés : les cordes, le biscuit, les lanternes, tout ce que vous avez emporté pour Sorne et rapporté de Sorne.",
      { if: PLOMB, text: "Le sergent mord une pièce de ta besace, puis une autre, et les jette sur les pavés en riant. Du plomb sous une feuille d'or. Ses piquiers rient avec lui. Ils te laissent la besace." },
      { if: { all: [OR, { not: PLOMB }] }, text: "Quand ils ouvrent ce que tu rapportes, le sergent reste un long moment sans rien dire. Puis il envoie un piquier en courant vers l'île des Changeurs. Une heure plus tard, une charrette bâchée emporte l'or de la reine vers la Monnaie, entre deux rangs de piques bleues.", else: "Ils ne trouvent rien qui vaille d'être emporté. Le sergent t'en veut presque." },
      { if: CHARTE, text: "L'étui de cuir ciré passe de main en main. Le sergent l'ouvre, regarde la cire verte et l'écriture ancienne, et le referme. « Pour l'envoyé, dit-il. Il aime les vieux papiers. »" },
      "On vous relâche au coucher du soleil, avec un reçu signé d'une croix.",
      { with: "tibere", text: "Tibère se relève en grimaçant, les genoux raides. « Au Guet, on donnait au moins un reçu signé d'un nom », dit-il." },
    ],
    fx: { flag: "vf:fouille" },
    choices: [{ label: "Monter vers la place du Beffroi", to: "VF_duc_ville" }] },

  VF_duc_joncs: { act: "V", title: "Les roseaux", place: "joncs",
    text: [
      "Vous laissez la Salve à bâbord et vous entrez dans les roseaux par une passe invisible jusqu'au moment de la prendre. Les tiges se referment derrière la poupe. Au loin, le bruit de la ville arrive en morceaux : une trompette, un tambour, une cloche qui sonne à contretemps.",
      { if: { has: "joncs:brules" }, text: "Les Joncs-Bas ont repoussé sur leurs pilotis noircis : des cabanes neuves, en planches encore blondes, entre les poteaux brûlés de la tempête.", else: "Les Joncs-Bas dorment sur leurs pilotis, les filets tendus entre les maisons, une lampe à chaque fenêtre tournée vers le chenal." },
      { if: { not: { has: "iit:ancolie_blessee" } }, text: "Mère Ancolie vous attend au bout du ponton, assise, ses mains de dentellière posées sur les genoux. Elle tourne la tête vers toi avant que tu aies parlé. « {{oreille#vf_duc_ancolie|Le duc ne viendra pas jusqu'ici|Le duc viendra ici l'an prochain avec ses arpenteurs, et la Charte sera notre seul titre}}, dit-elle. Montre-moi ce que tu rapportes. »" },
      { if: { has: "iit:ancolie_blessee" }, text: "Depuis la tempête, Mère Ancolie reste chez elle. C'est une de ses arrière-petites-filles qui vous attend, une gamine de douze ans, et qui vous conduit à elle." },
      { with: "lison", text: "Lison amarre sans un mot, puis reste debout dans la barque, les bras ballants, comme quelqu'un qui revient chez soi et ne sait plus où se mettre." },
    ],
    choices: [
      { label: "Laisser la Charte aux Joncs-Bas, sous le plancher de Mère Ancolie", hide: { not: CHARTE }, fx: { flag: "vf:charte_joncs", fac: { taiseurs: 10, hautes: 5 } }, to: "VF_duc_ville" },
      { label: "Garder tout avec toi et entrer en ville par les canaux, à la nuit", to: "VF_duc_ville" },
    ] },

  VF_duc_ville: { act: "V", title: "La place du Beffroi", place: "beffroi", hub: true,
    text: [
      { first: true, text: "La place du Beffroi est pleine de soldats désœuvrés. Ils ont dressé leurs faisceaux de piques devant la façade du Conseil, allumé des feux sur les pavés, et tendu des cordes à linge entre les colonnes. Les Salvézans passent le long des murs, vite, sans regarder." },
      { first: true, text: "Au sommet du Beffroi de la reine, à la place de la bannière de la République, pendent trois bannières bleues, brodées de la tour d'argent d'Aveline. Le vent les fait claquer contre les cadrans de l'horloge." },
      { again: true, text: "Les bannières bleues claquent au sommet du Beffroi. Sous les arcades, un soldat apprend à un enfant à jouer aux osselets." },
      { if: { has: "vf:port_force" }, text: "Des soldats passent de feu en feu, une description à la main : ceux qui ont jeté des piquiers à l'eau, au port. Tu rabats ton capuchon et tu longes les arcades." },
      "Sur la porte du Conseil, on a cloué une affiche fraîche, l'encre encore brillante : *{{loupe#vf_duc_affiche|Au nom de Son Altesse le duc d'Aveline, la ville de Salvèze est prise sous sa protection ; les biens, les maisons et les franchises sont garantis à chacun|Les biens de la Banque Marrel et des maisons qui n'ont pas signé avant la Saint-Jean seront saisis au profit du trésor ducal ; liste ci-jointe, à compléter}}.*",
      { if: { not: { has: "prevot:dejoue" } }, text: "Sous l'affiche, une deuxième feuille, plus petite : *Le gouverneur, Haumont Delisle.*" },
      { if: { has: "prevot:dejoue" }, text: "Sous l'affiche, une deuxième feuille, plus petite : *Pour le duc, son envoyé, Amaury de Sauveterre.*" },
    ],
    choices: [
      { label: "Entrer au Conseil, où l'on prête serment", hide: { seen: "VF_duc_conseil" }, to: "VF_duc_conseil" },
      { label: "Demander audience à l'envoyé du duc", hide: { any: [{ seen: "VF_duc_rachat" }, { seen: "VF_duc_cede" }, { seen: "VF_duc_refus" }] }, to: "VF_duc_amaury" },
      { label: "Faire recopier la liste de l'affiche et la porter aux Changeurs", hide: { any: [{ not: { voile: "vf_duc_affiche" } }, { seen: "VF_duc_liste" }] }, to: "VF_duc_liste" },
      { label: "Descendre au quai des Lanternes", big: true, to: "VF_duc_quai" },
    ] },

  VF_duc_liste: { act: "V", title: "La liste", place: "changeurs",
    text: [
      "Tu recopies la liste au dos d'un reçu, à la lueur d'un feu de soldats qui ne lisent pas. Elle compte quarante-deux noms de maisons. La Banque Marrel vient la première. Les Fourcaud et les Vernier n'y sont pas : ils ont signé.",
      "Sur l'île des Changeurs, les volets de la Banque sont fermés. Un commis t'ouvre une porte de service, puis Corisande Marrel elle-même, en robe de chambre, une bougie à la main. Elle lit la liste debout, sans lunettes. « {{oreille#vf_duc_cori|Merci de votre peine|Je voulais votre mort ou votre service, et c'est vous qui venez m'avertir}} », dit-elle.",
      "Avant de te laisser repartir, elle retire de son doigt une bague à cachet et la pose dans ta main. « On ne me croira pas si je dis que je vous dois quelque chose, dit-elle. Montrez ceci. »",
      "Elle passe la nuit à faire sortir ses registres par les égouts de la reine, sur des barques de pêcheurs. Au matin, les coffres de la Banque Marrel sont vides, et les gens du duc ne trouvent que des bureaux.",
    ],
    fx: { flag: ["vf:liste_corisande", "tresor:vf_cachet"], fac: { banque: 10 }, ep: ["perso", 800], item: "vf_tr_cachet", clock: { tresors: 1 } },
    choices: [{ back: "VF_duc_ville" }] },

  VF_duc_conseil: { act: "V", title: "Le serment", place: "beffroi",
    text: [
      "La grande salle du Conseil sent la cire froide et la sueur. On a retiré les bancs des quarante maisons et mis à leur place une table couverte d'un drap bleu. Une trentaine de marchands attendent en file, chapeau à la main, pour jurer fidélité au duc sur un évangéliaire qu'on a fait venir de la cathédrale.",
      { if: { not: { has: "prevot:dejoue" } }, text: "Haumont Delisle préside, assis, en robe de velours neuve. Il reçoit chaque serment d'un petit signe de tête. Quand il te voit entrer, il continue de sourire. « Nous avons sauvé la ville de la ruine, dit-il à la salle. {{oreille#vf_duc_delisle|Il n'y avait pas d'autre chemin|J'ai soixante et onze ans, et je voulais mourir dans un palais plutôt que dans une maison de commerce}}. »" },
      { if: { has: "prevot:dejoue" }, text: "C'est un capitaine d'Aveline qui préside, un homme roux qui s'ennuie. Delisle est absent. On dit que le duc le fait chercher, et qu'il hésite encore entre la corde et la récompense." },
      "Un vieux marchand de draps se penche vers toi dans la file. « {{oreille|On jure, on attend, on verra|J'ai déjà fait coudre la bannière bleue que je pendrai à ma fenêtre demain matin}} », dit-il tout bas.",
    ],
    choices: [
      { label: "Répéter tout haut, devant la salle, ce que Delisle vient de penser", hide: { any: [{ not: { voile: "vf_duc_delisle" } }, { has: "prevot:dejoue" }] }, fx: { flag: "vf:delisle_hue", ep: ["perso", 1000] }, to: "VF_duc_hue" },
      { label: "Ressortir sur la place", back: "VF_duc_ville" },
    ] },

  VF_duc_hue: { act: "V", title: "Le palais", place: "beffroi",
    text: [
      "Tu le dis comme tu l'as entendu, mot pour mot, d'une voix claire : le palais, la maison de commerce, les soixante et onze ans. La salle se tait. Delisle cesse de sourire.",
      "Puis quelqu'un rit, au fond, un rire bref de marchand qui a compris. Un deuxième rit. Le capitaine d'Aveline, à côté de Delisle, regarde le gouverneur comme on regarde un cheval qu'on vient d'acheter trop cher.",
      "Les gardes te font sortir sans te toucher. Dans la file des marchands, trois hommes remettent leur chapeau et s'en vont sans avoir juré.",
    ],
    choices: [{ back: "VF_duc_ville" }] },

  VF_duc_amaury: { act: "V", title: "L'envoyé", place: "beffroi",
    text: [
      "Amaury de Sauveterre t'attend dans le cabinet du prévôt, au premier étage du Conseil, les bottes sur le bureau. Il les retire quand tu entres. « {hero}, dit-il. On m'a dit que vous rentriez de la mer. On m'a dit beaucoup de choses sur ce que vous rapportiez. Asseyez-vous. »",
      { if: { has: "ivc:amaury_honneur" }, text: "Il te sert lui-même un verre de vin blanc. Il se souvient de vous au Conseil, et il te le dit sans détour." },
      { if: { has: "vt:aveline_gagne" }, text: "« Mon capitaine m'a raconté la salle sous la mer, dit-il. Il vous a laissé{e} en vie parce que le jour se levait. Il le regrette un peu. Moi, non. »" },
      { if: { all: [VRAI, { not: { has: "vf:fouille" } }] }, text: "« Le duc veut quatre millions de ducats, dit-il. Vous en avez peut-être une partie dans votre cale. Je vous propose un marché d'homme à homme : l'or de la reine au duc, et les franchises de Salvèze écrites, scellées, garanties. La ville garde son Conseil, ses juges, ses foires. Le duc garde les clés et le péage. »" },
      { if: { all: [CHARTE, { not: { has: "vf:fouille" } }, { not: { has: "vf:charte_joncs" } }] }, text: "« Et l'autre chose, dit-il plus bas. La Charte. Le duc s'en servirait pour casser les titres de la Banque et de ses amis. Les gens des marais auraient leurs terres, sous la loi d'Aveline. C'est peut-être ce que voulait votre reine. »" },
      { if: { has: "vf:fouille" }, text: "« Mes hommes ont déjà pris au port ce que vous rapportiez, dit-il. Je vous le dis franchement, pour que nous perdions moins de temps. »" },
      "« Le duc tiendra parole, ajoute-t-il. {{oreille#vf_duc_amaury|Il l'a toujours fait|Il tiendra parole tant que je serai vivant pour le lui rappeler, et il tousse du sang depuis l'hiver}}. »",
    ],
    choices: [
      { label: "Donner l'or de la reine au duc, contre les franchises de la ville", hide: { any: [{ not: VRAI }, { has: "vf:fouille" }] }, to: "VF_duc_rachat" },
      { label: "Remettre la Charte au duc, pour les gens des Hautes-Eaux", hide: { any: [{ not: CHARTE }, { has: "vf:fouille" }, { has: "vf:charte_joncs" }] }, to: "VF_duc_cede" },
      { label: "Lui demander qui gouvernera quand le duc sera mort", hide: { not: { voile: "vf_duc_amaury" } }, fx: { flag: "vf:amaury_sait", regard: { amaury: "admiratif" } }, to: "VF_duc_refus" },
      { label: "Refuser, et garder ce que tu as", to: "VF_duc_refus" },
    ] },

  VF_duc_rachat: { act: "V", title: "Les franchises", place: "beffroi",
    text: [
      "Le marché se signe le soir même, sur le bureau du prévôt, entre deux chandelles. Amaury écrit lui-même les franchises, de sa main fine et penchée, et il les lit à voix haute à mesure : le Conseil des Comptoirs, les juges de la ville, les foires de la Saint-Michel, le droit de lever ses propres impôts. Le sel des Hautes-Eaux franc de péage. Le duc garde la porte des Sauniers, le Beffroi, et un gouverneur.",
      "*{{loupe#vf_duc_franchises|Fait à Salvèze, pour le duc, par son envoyé|Fait à Salvèze, pour le duc, par son envoyé, qui en répond sur sa tête, et qui la donnerait volontiers}}.*",
      "Les coffres de la reine partent pour Aveline à l'aube, sur six chariots, entre deux rangs de cavaliers. Sur leur passage, les Salvézans se découvrent, sans savoir s'ils saluent l'or, la reine ou le duc.",
      { with: "lison", text: "Lison regarde passer les chariots. « Trois siècles au fond de la mer, dit-elle, pour finir dans les caves d'un duc. » Elle hausse les épaules. « Au moins, il les a payés. »" },
    ],
    fx: { flag: "vf:franchises", fac: { conseil: 15 }, ep: ["perso", 1500] },
    choices: [{ back: "VF_duc_ville" }] },

  VF_duc_cede: { act: "V", title: "La Charte au duc", place: "beffroi",
    text: [
      "Tu poses l'étui de cuir sur le bureau. Amaury l'ouvre avec précaution, déroule la Charte sous la chandelle et la lit jusqu'au bout, les lèvres serrées, en suivant les lignes du doigt sans toucher l'encre.",
      "« Cette femme savait écrire, dit-il enfin. Le duc fera lire ceci à Aveline, devant sa cour. Puis il cassera les titres de la Banque Marrel, des Fourcaud, des Vernier, et il rendra les terres des marais à ceux qui les ont gagnées sur la mer. {{oreille#vf_duc_cede|C'est une justice|C'est une justice, et c'est aussi la façon la moins chère de tenir les marais pendant cent ans}}. »",
      { if: { has: "vn:duc_brule" }, text: "Tu lui demandes s'il en répond sur sa tête. Amaury te regarde longtemps. « Sur la mienne, dit-il. Le duc avait d'autres projets pour ce papier. Je les connais. Je les changerai. »" },
      { with: "lison", text: "Lison s'est raidie à côté de toi. Elle regarde la Charte entre les mains d'Amaury comme on regarde un enfant qu'on confie à des inconnus." },
    ],
    fx: { flag: "vf:charte_duc", fac: { hautes: 10, taiseurs: -10, banque: -15 }, ep: ["perso", 1500] },
    choices: [{ back: "VF_duc_ville" }] },

  VF_duc_refus: { act: "V", title: "Le temps du duc", place: "beffroi",
    text: [
      "Amaury t'écoute jusqu'au bout. Puis il se lève, ouvre la fenêtre sur la place, et regarde les bannières bleues qui claquent au sommet du Beffroi.",
      { if: { has: "vf:amaury_sait" }, text: "« Son fils, dit-il sans se retourner. Il a onze ans. Il aime les chevaux et il a peur de l'eau. » Il referme la fenêtre. « Vous voyez que je vous dois quelque chose, maintenant. Gardez ce que vous avez. Je n'ai rien vu. »" },
      { if: { not: { has: "vf:amaury_sait" } }, text: "« Gardez ce que vous avez, dit-il. Le duc a le temps. Les villes, ça se mange lentement, comme les artichauts. Vous reviendrez me voir, ou vos enfants viendront voir les miens. »" },
      "Il te raccompagne lui-même jusqu'à l'escalier, avec une courtoisie parfaite.",
    ],
    choices: [{ back: "VF_duc_ville" }] },

  VF_duc_quai: { act: "V", title: "Le quai des Lanternes", place: "quai",
    text: [
      "Le quai des Lanternes a peu changé. Les brocanteurs ont rentré leurs étals, les chercheurs de choses perdues fument sur le pas de leur porte. Deux soldats d'Aveline marchandent une épée rouillée au vieux Galabru, dans un salvézan appris la veille.",
      "Sur la porte de la boutique Carrus, quelqu'un a cloué un billet de logement : *quatre hommes, un sergent*. Les volets sont ouverts. À l'intérieur, des soldats ont accroché leurs cuirasses aux crochets où Odeline pendait les clés perdues.",
      "La boutique {{echo#vf_duc_boutique|résonne de voix étrangères et de rires|garde, sous les rires des soldats, la voix d'Odeline, la veille des Lanternes : « Si un jour ils viennent, ceux du nord, tu fermes boutique et tu pars aux marais. Les marais, personne ne les prend »}}.",
      { with: "fauvette", text: "Fauvette regarde par la fenêtre, puis elle te regarde. « Je peux les faire partir en trois nuits, dit-elle. Leurs bottes, leurs ceinturons, leur solde. Ils demanderont à loger ailleurs. »" },
    ],
    choices: [{ label: "Monter au Beffroi à l'heure de midi", big: true, to: "VF_duc_fin" }] },

  VF_duc_fin: { act: "V", title: "Les bannières d'Aveline", place: "beffroi", end: true, epilogue: true, fx: END("duc"),
    text: [
      "À midi, la place du Beffroi est pleine. Les Salvézans sont venus voir si l'horloge de la reine sonnerait encore sous les bannières d'un autre. Les soldats sont venus voir les Salvézans.",
      "La grande aiguille touche le haut du cadran. Les portes de bronze s'ouvrent. La reine sort la première, en robe de cuivre vert, puis les sept muets, l'un après l'autre, la main sur la bouche. Ils font le tour de la galerie, sous les trois bannières bleues, et rentrent. La cloche sonne douze coups. Personne sur la place ne parle avant le dernier.",
      { if: CORNET, text: "Tu as le cornet d'os à l'oreille. Autour de toi, la foule se remet à parler, et les mots tremblent dans toutes les bouches." },
      "Une boulangère, à ta gauche, dit à sa voisine : « {{oreille|Ils paient en bonne monnaie, au moins|Mon fils est parti avec les déserteurs, et s'il revient il sera pendu sous ces bannières}}. » Derrière toi, Ermance Mabire, la capitaine du Guet, qui porte encore son ancienne cuirasse de cuir, dit à un sergent bleu : « {{oreille|Mes hommes sont à votre service|Mes hommes ont gardé leurs hallebardes et leurs noms, et ils savent où vous dormez}}. »",
      { if: { has: "vf:franchises" }, text: "Sur la porte du Conseil, on a cloué les franchises scellées de cire bleue, à côté de l'affiche du duc. Les gens les lisent à voix haute pour ceux qui ne savent pas lire. Le Conseil des Comptoirs siégera demain, sous un gouverneur. Il siégera." },
      { if: { has: "vf:charte_duc" }, text: "On dit déjà, au port, qu'un clerc d'Aveline est parti pour les marais avec des arpenteurs et une copie de la Charte, et que la Banque Marrel a fermé ses volets pour de bon." },
      { if: { has: "vf:charte_joncs" }, text: "La Charte dort sous le plancher de Mère Ancolie, aux Joncs-Bas. Le duc ignore qu'elle existe. Les Taiseurs savent attendre un autre siècle." },
      { if: { all: [CHARTE, { has: "vf:fouille" }] }, text: "La Charte est partie pour Aveline dans la sacoche d'un courrier, avec le reçu signé d'une croix. Personne ne sait ce que le duc en fera." },
      { if: { all: [OR, { not: PLOMB }, { has: "vf:fouille" }] }, text: "L'or de la reine est dans les caves de la Monnaie, sous la garde des piques bleues. Il paiera la solde de l'armée qui tient la ville." },
      { if: { has: "vf:sergent_tanneurs" }, text: "Sous les arcades, tu reconnais le sergent du port. Il porte un pain sous le bras, pour sa mère, rue des Tanneurs. Il te voit, et il détourne les yeux le premier." },
      { if: { has: "tresor:vf_cachet" }, text: "Dans ta poche, tu tournes la bague à cachet de Corisande Marrel. Elle est partie cette nuit vers le sud, avec ses registres. La bague est restée." },
      { with: "lison", text: "Lison est contre ton épaule. « {{oreille#vf_duc_lison|On rentre aux Joncs, toi et moi|Je rentre aux Joncs, et si tu viens, je saurai ce que tu as choisi}} », dit-elle sans te regarder." },
      { with: "tibere", text: "Tibère regarde la bannière bleue, puis ses mains. « {{oreille|Ils auront besoin de sergents qui connaissent les rues|Je porterai leur bleu s'il le faut, pour que Rosalie mange, et j'en ai honte d'avance}} », dit-il." },
      { with: "salome", text: "Salomé a déjà le dos tourné à la place. « La mer est à personne, dit-elle. Je rentre à Port-Vasier. Tu sais où me trouver. »" },
      { with: "fauvette", text: "Fauvette mange une oublie volée à un marchand bleu. « {{oreille|Les toits ne changent pas de maître|J'ai passé la nuit sur le toit du Beffroi à regarder la mer, j'avais peur que tu ne reviennes pas}} », dit-elle, la bouche pleine." },
      { with: "gildas", text: "Frère Gildas regarde la reine de cuivre rentrer dans sa niche. « Elle a déjà vu une ville tomber, dit-il. Elle tient encore debout. »" },
      { after: "voile:vf_duc_pecheur", text: "Sous les arcades, tu reconnais un homme à la ressemblance : le frère du pêcheur, celui qui gardait la porte des Sauniers. Il porte déjà une écharpe bleue. Il regarde ses souliers." },
      "Tu restes sur la place jusqu'à ce que les soldats allument leurs feux. Tu {{miroir#vf_duc_miroir|as fait ce que tu pouvais, avec ce que tu avais|as su, quelque part sous la mer, que la ville tomberait, et tu as continué de chercher quand même, parce que chercher, c'est ce que tu sais faire}}.",
    ] },
});

// ==================================================================== VF_charte: the Charter read in public
var R6 = { relics: { min: 6 } }, R4 = { relics: { min: 5 } };   // relics count the Charter (f_sorne) with the leaves
Object.assign(P, {
  VF_charte: { act: "V", title: "La remontée", place: "sorne",
    fx: { ep: ["seance", 2000] },
    text: [
      "Tu roules la Charte dans son étui de cuir ciré, et l'étui dans la toile cirée où dorment déjà les feuillets du Registre. Tu sangles le tout contre ta poitrine, sous ta chemise, si serré que tu sens ton cœur cogner contre le cuir.",
      { if: PLEIN, text: "Les coffres de la reine descendent derrière toi, au bout de la corde du treuil, jusque dans la barque. Ils paieront peut-être le duc. Ils sont lourds, et tu les regardes à peine." },
      { if: PARTIE, text: "Chacun porte une besace d'or sur l'épaule. Le reste demeure sous la mer. Tu regardes à peine les besaces." },
      { if: { not: OR }, text: "L'or de la reine reste où il est, en piles sur les dalles de la salle, sous la mer revenue. Tu ne te retournes pas." },
      "Tu descends de la tour de la Reine par l'échelle de corde, jusqu'à la barque qui danse à son pied. Quand vous vous éloignez, la mer a repris toute la ville. Il ne reste de Sorne que la tour, seule au-dessus de l'eau, puis un trait, puis rien.",
      { with: "gildas", text: "Frère Gildas pose la main à plat sur ta poitrine, sur le cuir de l'étui, sans rien dire, le temps d'un souffle. Puis il la retire." },
      { with: "lison", text: "Lison regarde l'endroit où la ville a disparu. « {{oreille#vf_ch_lison|Ma grand-mère va me tuer|Ma grand-mère va pleurer, et je ne l'ai jamais vue pleurer}} », dit-elle." },
      "Tu {{miroir#vf_ch_raison|rapportes la Charte pour les gens des marais, pour la justice, pour la reine|rapportes la Charte parce que tu veux, une fois, être celui ou celle qu'on écoute sur la place, et tu le sais}}.",
    ],
    choices: [{ label: "Mettre le cap sur Salvèze", big: true, to: "VF_ch_passe" }] },

  VF_ch_passe: { act: "V", title: "La passe de la Salve", place: null,
    text: [
      "À l'embouchure de la Salve, deux galères de la Banque Marrel attendent, bord à bord, en travers du chenal. Les besants d'or brillent sur leurs bannières noires. Les arbalétriers sont déjà sur les plats-bords.",
      "Une chaloupe s'avance. À la proue, un capitaine en manteau noir porte un porte-voix de cuivre. « Au nom de la Banque, crie-t-il. Vous portez un bien qui lui appartient. Rendez-le, et passez. {{oreille#vf_ch_capitaine|Madame vous laissera la vie et le reste|Mes rameurs n'ont pas touché leur solde depuis la Chandeleur, et je ne sais pas s'ils tireront}}. »",
      { if: { has: "lothaire:allie" }, text: "Lothaire Brunel se penche à ton oreille. « Je connais chaque homme de ces deux bords, dit-il. Je sais lequel a une fille à doter et lequel boit. Laissez-moi leur parler. »" },
      { if: { has: "basse:taiseurs" }, text: "Sur ta droite, dans les roseaux, une lanterne voilée s'allume, s'éteint, s'allume : les Taiseurs connaissent une autre passe." },
    ],
    choices: [
      { label: "Crier aux rameurs le nombre de mois de solde qu'on leur doit", hide: { not: { voile: "vf_ch_capitaine" } }, fx: { flag: "vf:rameurs_banque", ep: ["perso", 1000] }, to: "VF_ch_port" },
      { label: "Laisser Lothaire parler aux équipages", hide: { not: { has: "lothaire:allie" } }, fx: { flag: "vf:lothaire_passe" }, to: "VF_ch_port" },
      { label: "Suivre la lanterne des Taiseurs dans les roseaux", hide: { not: { has: "basse:taiseurs" } }, to: "VF_ch_port" },
      { label: "Passer par les hauts-fonds, à ras des bancs de vase", test: { dom: "nature", diff: -20, label: "Raser les bancs", help: [SAL, LIS, { if: { item: "ivm_astrolabe" }, v: 10 }] },
        win: { to: "VF_ch_port" }, lose: { to: "VF_ch_abordage" } },
      { label: "Forcer le passage à la rame et à l'épée", fight: { title: "La passe de la Salve", enemies: [{ id: "spadassin", n: 4 }],
        win: { to: "VF_ch_port" }, lose: { to: "VF_ch_abordage" },
        flee: { label: "Virer de bord vers les roseaux", dom: "nature", diff: -10, to: "VF_ch_abordage" } } },
    ] },

  VF_ch_abordage: { act: "V", title: "L'abordage", place: null,
    text: [
      "La galère vous prend par le travers. Les grappins mordent le bordage, des hommes sautent, et l'un d'eux arrache ta chemise d'un coup de crochet. L'étui de cuir roule sur le pont. Un spadassin le ramasse et court vers le bord pour le jeter à l'eau.",
      { with: "salome", text: "Salomé le cueille d'un coup d'épaule au moment où il lève le bras. Ils passent tous les deux par-dessus bord. Elle remonte la première, l'étui entre les dents, une entaille au front." },
      { with: "tibere", text: "Tibère attrape le spadassin par le col et par la ceinture, comme on attrape un ivrogne à la sortie d'une taverne, et le soulève. L'étui tombe à ses pieds. Il le ramasse sans lâcher l'homme." },
      { with: "fauvette", text: "Fauvette passe entre les jambes du spadassin. Quand il arrive au bord, il n'a plus rien dans la main. Il la regarde sans comprendre. Elle lui fait un petit signe." },
      { without: "any", text: "Tu te jettes sur lui. Vous tombez ensemble sur le pont, l'étui entre vous deux, et tu frappes jusqu'à ce qu'il le lâche." },
      "Le flot vous dégage de la galère. Les rameurs de la Banque gardent les avirons levés et regardent leur capitaine, qui regarde la ville.",
    ],
    fx: { pv: -5 },
    choices: [{ label: "Remonter la Salve jusqu'à Salvèze", to: "VF_ch_port" }] },

  VF_ch_port: { act: "V", title: "Le port aux Sauniers", place: "port",
    text: [
      "La nouvelle est arrivée avant toi, par les barques de pêche, par les cris d'une rive à l'autre. Quand tu accostes au port aux Sauniers, le quai est noir de monde : des sauniers en sabots, des dentellières, des débardeurs, des gamins sur les épaules de leurs pères. Personne ne crie. Ils regardent ta poitrine.",
      { if: { has: "vf:rameurs_banque" }, text: "Dans la foule, des rameurs des galères de la Banque, encore en casaque noire, crient ton nom avec les autres. Ils ont rangé leurs avirons au premier mot sur leur solde." },
      { if: { has: "vf:lothaire_passe" }, text: "Derrière ta barque, les deux galères de la Banque remontent la Salve à petits coups d'avirons. Lothaire Brunel les regarde accoster, les gants à la main. Il a parlé à chaque homme par son nom." },
      { if: { is: { ivc_dejoue: "conseil" } }, text: "Le prévôt provisoire a envoyé le Guet. Ermance Mabire fend la foule à la tête de vingt gardes. « Le Conseil siégera demain à midi, dit-elle. Vous y serez entendu{e}. D'ici là, mes hommes dorment devant votre porte. »" },
      { if: { is: { ivc_dejoue: "envoye" } }, text: "Un page d'Amaury de Sauveterre t'attend en haut des marches, avec un billet : *Le duc ne traite qu'avec la République. Lisez-lui ce que vous avez trouvé. Je serai au premier rang.*" },
      { if: { is: { ivc_dejoue: "rue" } }, text: "Les gamins des toits, les sauniers et les forgerons du Guet font une haie jusqu'à la place. Le prévôt Delisle préside toujours le Conseil. Il a fait annoncer une séance pour le lendemain midi, « pour entendre ce qu'on rapporte de la mer »." },
      { if: { not: { any: [{ is: { ivc_dejoue: "conseil" } }, { is: { ivc_dejoue: "envoye" } }, { is: { ivc_dejoue: "rue" } }] } }, text: "Le Guet arrive tard, en désordre. On te dit que le Conseil siégera demain à midi, et qu'il entendra ce que tu rapportes." },
      "Une vieille saunière te prend la main au passage et la serre très fort. « {{oreille#vf_ch_sauniere|Que Dieu vous garde|Mon grand-père avait un champ de sel à son nom, et je l'ai vu mourir dans celui d'un autre}} », dit-elle.",
    ],
    choices: [{ label: "Passer la nuit à la boutique du quai des Lanternes", to: "VF_ch_nuit" }] },

  VF_ch_nuit: { act: "V", title: "La dernière nuit", place: "quai",
    takes: "night",
    text: [
      "La boutique Carrus sent la poussière et le froid. Tu allumes la lampe d'Odeline. Tu poses l'étui de cuir sur l'établi, là où était la boîte au cornet, et tu t'assieds devant.",
      "La boutique {{echo#vf_ch_boutique|est silencieuse, à part la lampe qui grésille|garde la voix d'Odeline, un soir d'hiver, il y a des années : « Les gens croient qu'on trouve les choses. On ne trouve rien. On se souvient de l'endroit où elles étaient »}}.",
      "Vers minuit, on frappe trois coups à la porte. Par la fenêtre, tu vois une chaise à porteurs arrêtée sur le quai, sans armoiries, et deux porteurs qui soufflent dans leurs mains.",
      { with: "tibere", text: "Tibère se lève et prend sa masse. « Je connais cette chaise, dit-il. Je l'ai suivie trois ans pour le compte de quelqu'un d'autre. »" },
    ],
    choices: [
      { label: "Ouvrir à Corisande Marrel", to: "VF_ch_corisande" },
      { label: "Laisser la porte fermée et attendre le jour", to: "VF_ch_matin" },
    ] },

  VF_ch_corisande: { act: "V", title: "Corisande", place: "quai",
    text: [
      "Corisande Marrel entre seule. Elle a soixante-sept ans, une canne d'ébène, un manteau de loutre sur une robe de deuil. Elle regarde la boutique, les étagères, l'escalier de la cave, et elle s'assied sur le tabouret d'Odeline sans qu'on l'y invite.",
      "« Je ne vous offrirai pas d'argent, dit-elle. Vous en avez refusé assez. Je viens vous dire ce qui se passera demain. Vous lirez. Les titres tomberont. La Banque tombera. Avec elle, la dette de la République, les salaires de trois mille commis, le pain des Halles qu'on achète à crédit. {{oreille#vf_ch_cori|La ville aura faim cet hiver, et vous l'aurez voulu|J'ai peur, pour la première fois depuis la mort de mon mari, et je ne sais pas de quoi}}. »",
      { if: { any: [{ has: "ivm:pacte_rompu" }, { has: "vt:pacte_rompu" }] }, text: "« Vous m'aviez donné votre parole, ajoute-t-elle. Vous me l'avez reprise. Je vous en veux moins que je ne le devrais. »" },
      { if: { has: "vt:cori_nom" }, text: "Elle a le visage qu'elle avait à Sorne, dans sa chaise à bras, quand elle t'a parlé du couteau. Elle ne le cache plus." },
      { if: { has: "vt:cori_vaincue" }, text: "Elle s'appuie sur sa canne plus lourdement qu'à Sorne. « Trois cents marches, dit-elle. Je les ai montées. Je les sens encore. »" },
      { if: { has: "vt:cori_berold" }, text: "« Vous m'avez promis Bérold, dit-elle encore. Une part de l'or, par votre main et pour son nom. Je compte sur vous pour cela aussi. »" },
      { if: { has: "vt:lothaire_tourne" }, text: "« Lothaire aussi, ajoute-t-elle. Vingt ans de service. Je l'ai congédié par billet, et c'est vous qui l'avez ramassé. »" },
    ],
    choices: [
      { label: "Lui promettre un an avant les premières saisies", fx: { flag: "vf:delai_corisande", fac: { banque: 10 } }, to: "VF_ch_matin" },
      { label: "Lui demander de se tenir à côté de toi demain, sur les marches", hide: { not: { voile: "vf_ch_cori" } }, fx: { flag: "vf:corisande_marches", ep: ["perso", 1500] }, to: "VF_ch_matin" },
      { label: "Lui dire que la ville a déjà faim, et depuis trois siècles", fx: { fac: { banque: -5, hautes: 5 } }, to: "VF_ch_matin" },
    ] },

  VF_ch_matin: { act: "V", title: "Les marches du Conseil", place: "beffroi",
    text: [
      "À midi moins le quart, la place du Beffroi est si pleine qu'on ne voit plus les pavés. Les gens sont montés sur les fontaines, aux fenêtres, sur les toits des arcades. Il y a des sauniers, des pêcheurs d'anguilles, des moines du Mont en bure grise, des commis de la Banque qui n'osent pas retirer leur chapeau.",
      "Sur les marches du Conseil, une rangée d'hommes en livrée verte barre la porte : les gardes des Fourcaud et des Vernier. Leur sergent pose la main sur sa garde. « Le Conseil entendra votre papier, dit-il. À huis clos. Par la petite porte. {{oreille#vf_ch_garde|Ce sont les ordres|Mon maître a fait chauffer le four de sa cuisine depuis l'aube, et il m'a dit d'y porter tout ce que vous tiendrez}}. »",
      { if: { has: "vf:corisande_marches" }, text: "Corisande Marrel est debout sur la plus haute marche, appuyée sur sa canne, en robe de deuil. Les gardes en livrée n'osent pas lui demander de se pousser. Elle te regarde monter vers eux." },
    ],
    choices: [
      { label: "Crier à la place ce que le sergent vient de penser", hide: { not: { voile: "vf_ch_garde" } }, fx: { ep: ["perso", 1000] }, to: "VF_ch_lecture" },
      { label: "Monter à côté de Corisande, qui t'attend sur la plus haute marche", hide: { not: { has: "vf:corisande_marches" } }, to: "VF_ch_lecture" },
      { label: "Rappeler la vieille loi : tout citoyen peut lire une pétition sur les marches", test: { dom: "social", diff: -10, label: "Invoquer la loi", help: [GIL, { if: { has: "registre:lu" }, v: 10 }] },
        win: { to: "VF_ch_lecture" }, lose: { to: "VF_ch_beffroi" } },
      { label: "Laisser la foule pousser, et monter avec elle", who: "tibere", test: { dom: "combat", diff: -10, label: "Forcer les marches", help: [TIB, SAL] },
        win: { to: "VF_ch_lecture" }, lose: { to: "VF_ch_beffroi" } },
      { label: "Monter au Beffroi par la porte des carillonneurs et lire d'en haut", who: "lison", to: "VF_ch_beffroi" },
    ] },

  VF_ch_beffroi: { act: "V", title: "La galerie de la reine", place: "beffroi",
    text: [
      "Tu prends l'escalier des carillonneurs, cent quatre-vingts marches dans le noir, jusqu'à la salle des rouages. Les poids descendent lentement le long de leurs chaînes. Tu passes derrière l'automate de la reine, dans l'odeur de graisse et de cuivre, et tu attends.",
      { with: "lison", text: "Lison t'ouvre la trappe de la galerie avec son couteau. « Midi, dit-elle. Quand ils sortent. Pas avant. »" },
      { with: "fauvette", text: "Fauvette est déjà sur la galerie, assise sur la balustrade, les pieds dans le vide au-dessus de la place. Elle te tend la main pour t'aider à passer." },
      "La grande aiguille touche le haut du cadran. Les portes de bronze s'ouvrent. La reine de cuivre sort sur la galerie, puis les sept muets, la main sur la bouche, et toi derrière eux, l'étui de cuir à la main. En bas, dix mille visages se lèvent en même temps.",
    ],
    fx: { flag: "vf:lu_beffroi" },
    choices: [{ label: "Lire", big: true, to: "VF_ch_lecture" }] },

  VF_ch_lecture: { act: "V", title: "La lecture", place: "beffroi",
    fx: { ep: ["seance", 2500] },
    text: [
      { if: { has: "vf:lu_beffroi" }, text: "La cloche sonne douze coups au-dessus de ta tête. Au douzième, la place se tait.", else: "La porte du Conseil s'ouvre. Tu montes jusqu'à la plus haute marche, tu te retournes vers la place, et la place se tait." },
      { if: { is: { ivm_charte: "lire" } }, text: "Tu l'avais dit à Mère Ancolie, avant la Grande Basse : devant le Conseil et devant le peuple. Tu y es." },
      "Tu déroules la Charte. La cire verte craque. Tu lis d'abord lentement, puis plus fort, pour que les derniers rangs entendent. *{{loupe#vf_ch_charte|Nous, Ysaure, reine du delta, voulons que les terres gagnées sur la mer appartiennent à ceux qui les ont gagnées, à eux et à leurs enfants, sans cens ni rachat|Et si cette charte est jamais cachée, que celui qui la retrouve la lise à voix haute, sur une place, devant ceux qu'elle concerne, car une loi qu'on tait est une loi qu'on vole}}.*",
      { if: { has: "vt:charte_lue_tour" }, text: "Tu l'as déjà lue une fois, en haut de la tour de la Reine, à la mer et aux bateaux. Ta voix connaît le chemin." },
      { if: { has: "registre:lu" }, with: "gildas", text: "Puis Frère Gildas monte à côté de toi et lit le Registre. Il lit le témoignage de la reine, dicté par signes à ses secrétaires, la nuit des Comptoirs : les noms des maisons, les noms des hommes, le couteau. Sa voix reste ferme. Personne ne bouge sur la place." },
      { if: { all: [{ has: "registre:lu" }, { not: { present: "gildas" } }] }, text: "Puis tu lis le Registre, feuillet après feuillet, tel que Mère Ancolie te l'a appris : les noms des maisons, les noms des hommes, le couteau. Tu buttes sur certains mots. Personne ne bouge sur la place." },
      { if: { not: { has: "registre:lu" } }, text: "Puis tu montres les feuillets du Registre, un à un, au-dessus de ta tête. Leurs signes te restent fermés. Quelqu'un, dans la foule, une vieille femme des Joncs-Bas, commence à traduire les signes à voix haute, et d'autres reprennent après elle, de rang en rang, jusqu'au fond de la place." },
      { if: R6, text: "Cinq feuillets et la Charte. Le Registre entier, tel que les Taiseurs l'ont caché, page après page, sans un trou." },
      { if: { all: [R4, { not: R6 }] }, text: "Il manque des feuillets au Registre. Ce qui reste suffit pour les noms et pour le couteau." },
      { if: { not: R4 }, text: "Il manque trop de feuillets au Registre. Ce qui reste dit le couteau, et quelques noms. Tu entends, sur les marches, les avocats des maisons qui comptent déjà les trous." },
      { if: { has: "vt:cori_apaisee" }, text: "Quand vient le nom des Marrel, tu le lis d'une voix égale, et tu ajoutes, comme tu l'as promis à Sorne, que le prénom de Corisande est absent du Registre." },
      { if: { has: "vt:cori_tous" }, text: "Tu lis tous les noms, celui des Marrel comme les autres, sans changer de voix. Au pied des marches, des têtes se tournent vers l'île des Changeurs." },
      { if: { has: "vt:lothaire_fidele" }, text: "Au pied des marches, Lothaire Brunel écoute sans son cornet, les gants à la main. Il remue les lèvres sur la signature." },
      { if: { has: "vn:aymeric_volonte" }, text: "La lettre d'Aymeric Vasse est dans ta besace, contre la Charte. Tu fais ce qu'elle demande, ici, devant tous." },
      { if: { has: "vt:avis_lison" }, with: "lison", text: "Lison est au premier rang, au pied des marches, comme elle l'a voulu. Elle a les poings serrés et les yeux secs." },
      { if: { all: [{ has: "vt:avis_aine" }, { has: "basse:taiseurs" }] }, text: "Dans la foule, l'Aîné des Taiseurs a ôté son capuchon de dentelle. Il pleure sans bruit, et les gens des marais autour de lui aussi." },
      "Quand tu te tais, il y a un long silence. Puis un homme, quelque part, dit le nom de la reine. Pas le surnom. Son nom.",
    ],
    choices: [{ label: "Entrer au Conseil", big: true, to: "VF_ch_conseil" }] },

  VF_ch_conseil: { act: "V", title: "Le vote", place: "beffroi",
    text: [
      "Les quarante maisons votent le soir même, debout, à main levée, sous les yeux de la place qui a envahi les tribunes. Les fenêtres sont ouvertes. On entend la foule respirer.",
      "Maître Fourcaud, qui possède la moitié des salines du sud, se lève le premier. « La Charte est authentique, dit-il. {{oreille#vf_ch_fourcaud|La République doit s'y soumettre|Si je vote contre, ils brûleront ma maison cette nuit, et j'ai mes petits-enfants à l'étage}}. » Il lève la main. Les autres le suivent, l'un après l'autre, comme on descend un escalier dans le noir.",
      { if: { has: "vn:acte_faux" }, text: "Tu poses sur la table la copie d'acte rapportée du bureau du greffier de Sorne. Les avocats des maisons la font passer de main en main, et elle revient plus vite qu'elle n'est partie." },
      { if: { has: "tresor:vn_sceau" }, text: "Puis tu poses le grand sceau des Comptoirs, sa poignée d'ivoire tournée vers les bancs. Le greffier du Conseil le reconnaît avant qu'on le lui demande, et il pâlit." },
      { if: { has: "vt:sceptre_preuve" }, text: "Tu poses aussi le sceptre de procession, la virole tournée vers les bancs. Maître Fourcaud la lit, et le passe à son voisin sans un mot." },
      { if: R4, text: "Les titres des Hautes-Eaux sont déclarés nuls, de la Saline de Grisemotte jusqu'aux pilotis de Port-Vasier. Les terres reviennent aux familles qui les ont gagnées sur la mer, sur preuve de leurs noms dans les vieux rôles.", else: "Les titres des Hautes-Eaux sont suspendus en attendant jugement. Le Conseil nomme une commission. Les avocats des maisons se frottent les mains : un Registre incomplet, cela se plaide des années." },
      { if: { has: "vf:delai_corisande" }, text: "Sur ta demande, le Conseil accorde un an avant les premières saisies. Dans les tribunes, des sauniers sifflent. D'autres les font taire." },
      { if: VRAI, text: "L'or de la reine, voté au trésor de la République, paiera le duc d'Aveline à la Saint-Jean." },
    ],
    fx: { fac: { hautes: 15, conseil: 5, banque: -15 } },
    choices: [{ label: "Le lendemain, aller sur l'île des Changeurs", to: "VF_ch_banque" }] },

  VF_ch_banque: { act: "V", title: "La chute de la Banque", place: "changeurs",
    text: [
      "Le lendemain, à l'ouverture, il y a trois mille personnes devant la Banque Marrel, avec leurs reçus de dépôt à la main. À midi, les commis ferment les grilles. À trois heures, ils ferment les volets.",
      { if: { has: "vf:corisande_marches" }, text: "Corisande Marrel sort à quatre heures, à pied, sans garde, par la grande porte. Elle traverse la foule, qui s'écarte. Arrivée sur le pont, elle se retourne vers toi. « {{oreille#vf_ch_cori_pont|Vous avez eu raison|Je suis soulagée, et je ne le dirai à personne d'autre}} », dit-elle, et elle s'en va." },
      { if: { not: { has: "vf:corisande_marches" } }, text: "Corisande Marrel reste à l'intérieur. On dit qu'elle est restée dans la salle des comptes jusqu'à l'aube, seule, à vérifier les registres ligne à ligne, comme si une erreur d'addition pouvait encore tout sauver." },
      { if: { any: [{ has: "lothaire:vaincu" }, { has: "lothaire:mort" }] }, text: "Dans le cabinet de Lothaire Brunel, les huissiers trouvent une collection de cornets, de clés et de cartes marines, et une paire de gants gris, neuve, dans sa boîte." },
      { if: { has: "lothaire:allie" }, text: "Lothaire Brunel se présente le même jour devant la commission, ses gants gris à la main, et demande à témoigner contre la maison qu'il a servie vingt ans. Il témoigne trois jours." },
    ],
    choices: [{ label: "Le procès du prévôt", to: "VF_ch_prevot" }] },

  VF_ch_prevot: { act: "V", title: "Le procès d'Haumont Delisle", place: "beffroi",
    text: [
      { if: { is: { ivc_chute: "cellule" } }, text: "On sort Haumont Delisle de sa cellule un matin de mai pour le juger dans la grande salle du Conseil. Il a maigri. Il porte encore sa robe de velours, et quelqu'un la lui a brossée." },
      { if: { is: { ivc_chute: "fuite" } }, text: "On ramène Haumont Delisle des Combes en charrette, entre deux gardes, au mois de mai. Sa nièce l'a livré pour la récompense. Il a encore de la boue d'Orle sur ses souliers." },
      { if: { is: { ivc_chute: "rue" } }, text: "Le soir même de la lecture, sur la place, quelqu'un dit enfin tout haut ce que Delisle avait voulu faire de la porte des Sauniers. Le prévôt est arrêté dans son fauteuil, au Conseil, en plein comité, avec sa chaîne au cou." },
      { if: { not: { any: [{ is: { ivc_chute: "cellule" } }, { is: { ivc_chute: "fuite" } }, { is: { ivc_chute: "rue" } }] } }, text: "Haumont Delisle est arrêté au Conseil, avec sa chaîne au cou, le lendemain de la lecture." },
      "On t'appelle à témoigner. Tu dis ce que tu as vu et ce que tu as entendu, y compris ce que tu as entendu sous les mots. Les juges ne savent pas quoi faire de cette dernière partie. Ils l'écrivent quand même.",
      { if: { has: "vn:page_marrel" }, text: "Tu poses devant les juges la page arrachée au registre des Marrel, sous la mer. Le président la lit deux fois, à voix basse. Haumont Delisle regarde le plafond." },
      "On laisse le dernier mot à l'accusé. « J'ai servi cette ville cinquante ans, dit-il. {{oreille#vf_ch_delisle|Je l'ai servie à ma façon|Je l'ai méprisée cinquante ans, ses marchands, ses pauvres et son odeur de poisson, et je voulais finir loin d'elle}}. »",
      "Il est condamné à la perte de ses biens et à l'exil perpétuel. Il quitte Salvèze par la porte des Sauniers, à pied, sans sa chaîne.",
      { if: { has: "vf:delisle_entendu" }, text: "Sous la voûte de la porte, il sort un mouchoir parfumé et le garde contre son nez jusqu'au pont." },
    ],
    fx: { flag: "vf:prevot_juge" },
    choices: [{ label: "Les années suivantes", to: "VF_ch_annees" }] },

  VF_ch_annees: { act: "V", title: "Les années de procès", place: "beffroi",
    text: [
      "Les procès durent sept ans. Les maisons plaident chaque champ de sel, chaque vasière, chaque pilotis. Les avocats deviennent riches. Les Archives de la République ouvrent une salle exprès, où Eustache Vauquelin fait venir des rôles vieux de trois siècles et les lit tout haut aux plaignants qui ne savent pas lire.",
      { if: VRAI, text: "Le duc d'Aveline est payé à la Saint-Jean, en or de la reine. Amaury de Sauveterre compte lui-même les coffres à la porte des Sauniers, signe le reçu, et repart avec ses troupes. Il te salue en passant, de son chapeau, du haut de son cheval." },
      { if: { not: VRAI }, text: "La Saint-Jean passe sans que le duc d'Aveline soit payé. Amaury de Sauveterre accepte un marché : la dette en sel, sur douze ans, et les salines des Hautes-Eaux en garantie. Les sauniers paient la rançon de la ville avec la terre qu'on vient de leur rendre. Ils le savent. Ils paient quand même." },
      { after: "voile:vf_ch_fourcaud", text: "Personne ne brûle la maison de Maître Fourcaud. Ses petits-enfants dorment à l'étage. Il te salue le premier, chaque fois que vous vous croisez sur le pont des Changeurs, et il ignore pourquoi tu lui souris." },
      { if: { has: "vt:carte_terres" }, text: "La carte de la mosaïque, avec ses noms de familles tracés champ par champ, reste ouverte sur la grande table des Archives pendant les sept ans. Elle abrège la moitié des procès. Les avocats des maisons la détestent." },
      { if: { has: "vt:avis_salome" }, text: "Sur la liste des familles des Hautes-Eaux, la commission inscrit, à ta demande, un nom de Port-Vasier qui n'avait aucune terre : Maïwenn Brac. Personne ne discute. Salomé vient lire la ligne elle-même." },
      "La Banque Marrel est liquidée en trois ans. Ses commis trouvent d'autres places, ou n'en trouvent pas. L'hiver qui suit la lecture, le pain des Halles coûte un liard de plus. L'hiver d'après, un liard de moins.",
    ],
    choices: [{ label: "Le premier sel des Hautes-Eaux", to: "VF_ch_joncs" }] },

  VF_ch_joncs: { act: "V", title: "Le premier sel", place: "joncs",
    text: [
      "Au premier été, les gens des Joncs-Bas te font venir pour la première récolte de sel sur des bassins à leur nom. Les sauniers ratissent la croûte blanche en chantant les chants de travail, ceux qui ont deux sens. Cette fois, ils les chantent fort.",
      { if: { not: { has: "iit:ancolie_blessee" } }, text: "Mère Ancolie est assise au bord du premier bassin, ses mains de dentellière sur les genoux. Elle tourne la tête vers toi. « {{oreille#vf_ch_ancolie|Tu as rompu trois siècles de silence|Tu as fait ce que nous n'avons jamais osé faire, et je t'en voudrai jusqu'à ma mort, et j'en suis fière}} », dit-elle." },
      { if: { has: "iit:ancolie_blessee" }, text: "Mère Ancolie est morte au printemps, dans son lit, pendant les procès. Sur sa dernière dentelle, Lison a lu à la loupe une seule ligne : *Ils l'ont lue sur la place.*" },
      "Une dentellière te tend une petite salière de corne noire, sculptée d'un motif de vagues, pleine du premier sel. Le couvercle {{pie#vf_ch_saliere|est un simple bouchon de corne|a un double fond où loge un anneau d'or au chiffre d'Ysaure, cadeau des Vasse à celui qui rendrait la Charte}}.",
      { with: "lison", text: "Lison verse une poignée de sel dans ta main. « Le premier, dit-elle. On le donne à celui qui a apporté la pluie, d'habitude. Tu as apporté autre chose. »" },
    ],
    choices: [{ label: "La nuit des Lanternes, un an après", big: true, to: "VF_ch_fin" }] },

  VF_ch_fin: { act: "V", title: "La Charte rendue", place: "quai", end: true, epilogue: true, fx: END("charte"),
    text: [
      "Un an après la Grande Basse, la nuit des Lanternes revient. Tu descends au quai avec une lanterne de papier huilé, comme tout le monde. Sur l'eau du canal, des centaines de petites flammes dérivent vers la mer, une par noyé de l'année.",
      "Il y a du monde sur le quai, plus que d'habitude : des gens des marais, venus en barque, qui n'étaient jamais entrés en ville le soir de la fête. Quand ils te reconnaissent, ils te saluent du signe des Joncs, deux doigts contre la paume, le pouce par-dessus.",
      { if: CORNET, text: "Tu portes le cornet d'os, par habitude. Les voix tremblent autour de toi, comme toujours." },
      "Un débardeur te tend une chope. « {{oreille|À la reine, et à toi|Je travaillais pour les Fourcaud, j'ai perdu ma place à cause de toi, et mes enfants mangent mieux qu'avant}} », dit-il. Une veuve de la rue des Dames pose sa lanterne à côté de la tienne. « {{oreille|Elle va loin, celle-là|C'est pour mon mari, qui était commis à la Banque, et qui s'est pendu en mars}} », dit-elle.",
      { if: { has: "vt:avis_tibere" }, with: "tibere", text: "Rosalie est venue avec son père. Elle se tient à deux pas de lui, et elle le regarde faire." },
      { with: "tibere", text: "Tibère pose sa lanterne sur l'eau avec des gestes de vieux soldat. « {{oreille#vf_ch_tibere|Pour personne en particulier|Pour l'homme que j'étais quand Lothaire me payait, qu'il aille au fond}} », dit-il." },
      { with: "fauvette", text: "Fauvette a appris à lire cet hiver. Elle a écrit un nom sur sa lanterne, en grosses lettres penchées : *Odeline*. « {{oreille|Elle me faisait peur|Elle m'a donné une pomme, une fois, le jour où je l'ai volée}} », dit-elle." },
      { with: "salome", text: "Salomé est montée de Port-Vasier pour la fête. Elle pose deux lanternes sur l'eau, l'une après l'autre, et garde pour elle le nom de la deuxième." },
      { with: "lison", text: "Lison est assise sur la troisième marche de la boutique, les genoux sous le menton. « {{oreille#vf_ch_lison_fin|Tu deviens célèbre, c'est insupportable|Reste, je n'ai jamais demandé à personne de rester}} », dit-elle." },
      { with: "gildas", text: "Frère Gildas pose sa lanterne sans un mot, les mains tremblantes pour une fois. Tu sais pour qui elle brûle. Il le sait aussi." },
      "Tu poses ta lanterne sur l'eau et tu la pousses du bout des doigts. Elle tourne, hésite, puis prend le courant. Tu {{miroir#vf_ch_miroir|la regardes partir en pensant à Odeline|la regardes partir en pensant à Odeline, et tu sais enfin que tu lui as pardonné de t'avoir caché la moitié de sa vie, et que c'était cela qui te pesait, plus que la dispute}}.",
    ] },
});

// ==================================================================== VF_republique: the gold to the Council, the Charter to the Taiseurs
Object.assign(P, {
  VF_republique: { act: "V", title: "Deux fardeaux", place: "sorne",
    fx: { ep: ["seance", 2000] },
    text: [
      "Au pied de la tour de la Reine, la mer revenue clapote contre les pierres. On descend l'or dans la barque par le treuil et à la chaîne, sans un mot.",
      { if: PLEIN, text: "Les trois coffres de la reine descendent l'un après l'autre au bout de la corde du treuil. Au dernier, la barque s'enfonce d'une main, et le bordé grince." },
      { if: PARTIE, text: "Les besaces passent de main en main. Ce que vous avez pu porter de l'or de la reine suffit à faire plier deux hommes." },
      "La Charte, dans son étui de cuir ciré, est restée contre ta poitrine. Tu sais à qui tu vas la donner. Tu ne sais pas encore à quelles mains.",
      { if: { has: "basse:taiseurs" }, text: "Dans la barque des Joncs, à vingt brasses, les trois Taiseurs attendent debout. Le plus vieux, l'Aîné, tend les deux mains, paumes en l'air, comme on attend qu'on y pose un pain." },
      { with: "lison", text: "Lison regarde l'étui, puis toi. Elle se tait. Elle a les mains derrière le dos." },
      { with: "gildas", text: "Frère Gildas se tient un peu à l'écart, dans sa bure trempée. Il est le Gardien. Il n'a pas besoin de tendre la main." },
    ],
    choices: [
      { label: "Remettre la Charte à l'Aîné des Taiseurs", hide: { not: { has: "basse:taiseurs" } }, fx: { set: { vf_charte_a: "aine" } }, to: "VF_rep_charte" },
      { label: "La remettre à Lison", hide: { not: { present: "lison" } }, fx: { set: { vf_charte_a: "lison" }, conf: { lison: 10 } }, to: "VF_rep_charte" },
      { label: "La remettre à Frère Gildas, le Gardien", hide: { not: { present: "gildas" } }, fx: { set: { vf_charte_a: "gildas" }, conf: { gildas: 10 } }, to: "VF_rep_charte" },
      { label: "La garder jusqu'aux Joncs-Bas et la porter toi-même à Mère Ancolie", fx: { set: { vf_charte_a: "joncs" } }, to: "VF_rep_charte" },
    ] },

  VF_rep_charte: { act: "V", title: "La Charte rendue au silence", place: "sorne",
    text: [
      { if: { is: { vf_charte_a: "aine" } }, text: "Tu poses l'étui dans les mains de l'Aîné. Il le garde fermé et le porte à son front, puis à sa bouche, puis le glisse sous sa capuche de dentelle. « {{oreille#vf_rep_aine|Elle retourne où elle doit être|Elle retourne sous le plancher, et mes petits-enfants mourront locataires des Fourcaud}} », dit-il." },
      { if: { is: { vf_charte_a: "lison" } }, with: "lison", text: "Lison prend l'étui à deux mains. Elle le garde un moment contre elle sans bouger. « {{oreille#vf_rep_lison|Ma grand-mère sera contente|Tu me donnes la seule chose que je ne voulais pas porter seule}} », dit-elle." },
      { if: { is: { vf_charte_a: "gildas" } }, with: "gildas", text: "Frère Gildas prend l'étui et le serre contre sa bure. « Je la garderai jusqu'à ce qu'on vienne me la prendre, dit-il. Et je ne laisserai personne me la prendre. » Il le dit comme on dit une heure." },
      { if: { is: { vf_charte_a: "joncs" } }, text: "Tu gardes l'étui sur toi. Tu le porteras aux Joncs-Bas, à Mère Ancolie, de ta main à la sienne. C'est une manière de dire que tu as compris ce qu'il vaut." },
      { if: { is: { ivm_charte: "rendre" } }, text: "Tu l'avais promis à Mère Ancolie, avant la Grande Basse. Tu tiens parole." },
      { if: { is: { ivm_charte: "lire" } }, text: "Tu avais promis à Mère Ancolie de la lire devant le peuple. Elle s'en souviendra. Toi aussi." },
      "Tu {{miroir#vf_rep_miroir|fais le choix raisonnable, celui qui sauve le plus de gens|fais le choix qui te permet de rentrer en ville sans avoir à monter sur les marches du Conseil, et tu en ressens du soulagement et de la honte à la fois}}.",
    ],
    choices: [{ label: "Prendre la mer avec l'or", big: true, to: "VF_rep_mer" }] },

  VF_rep_mer: { act: "V", title: "Les parts", place: null,
    text: [
      "Au milieu de la traversée, le vent tombe. La barque roule sur une houle lente, lourde de son or, et les rameurs se reposent sur leurs avirons. C'est le moment où les gens se mettent à compter.",
      { if: { has: "ivm:part_ecumeurs" }, text: "Riwal, le second de la Veuve Corbière, s'est installé sur le banc de poupe avec ses huit hommes. Il te sourit beaucoup. « Un dixième, dit-il. C'était le marché. {{oreille#vf_rep_riwal|On le prendra à Port-Vasier, bien pesé|On prendra tout à Port-Vasier, et on vous laissera sur la vase avec votre dixième}}. »" },
      { if: { has: "ivm:part_gouttieres" }, text: "Les enfants de la Reine des Gouttières sont descendus du gréement. Ils s'assoient autour des besaces, sans les toucher. Le plus grand dit : « Un quart. C'était le marché. Margaux a dit de compter devant toi. »" },
      { if: { not: { any: [{ has: "ivm:part_ecumeurs" }, { has: "ivm:part_gouttieres" }] } }, text: "Tes rameurs se regardent. L'un d'eux, un débardeur du port, dit enfin tout haut ce que les autres pensent : « Et nous ? On a ramé jusqu'à Sorne et retour. »" },
    ],
    choices: [
      { label: "Dire tout haut aux rameurs de Riwal ce qu'il prévoit pour eux à Port-Vasier", hide: { not: { voile: "vf_rep_riwal" } }, fx: { flag: "vf:riwal_dejoue", ep: ["perso", 1200] }, to: "VF_rep_port" },
      { label: "Payer à chacun sa part, ici, devant tout le monde", fx: { flag: "vf:parts_payees", fac: { ecumeurs: 10 } }, to: "VF_rep_port" },
      { label: "Leur parler de la ville qui attend cet or pour ne pas tomber", test: { dom: "social", diff: -20, label: "Convaincre l'équipage", help: [TIB, SAL, { if: { has: "basse:taiseurs" }, v: 10 }] },
        win: { fx: { flag: "vf:parts_promises" }, to: "VF_rep_port" }, lose: { to: "VF_rep_perte" } },
      { label: "Poser ta main sur ta lame", fight: { title: "Le partage", enemies: [{ id: "ecumeur", n: 3 }],
        win: { to: "VF_rep_port" }, lose: { to: "VF_rep_perte" },
        flee: { label: "Te réfugier à la poupe avec la barre", dom: "nature", diff: -10, to: "VF_rep_perte" } } },
    ] },

  VF_rep_perte: { act: "V", title: "Ce que la mer reprend", place: null,
    text: [
      "Dans la bousculade, une besace passe par-dessus bord. Puis une deuxième, arrachée par un homme qui saute avec elle dans la barque de Riwal, ou dans la mer, tu ne vois pas bien. Quand le calme revient, il manque de l'or, et un rameur.",
      { with: "salome", text: "Salomé a pris la barre et met la barque face à la houle. « Assis, dit-elle. Tous. Le prochain qui se lève, je le laisse nager jusqu'à Salvèze. » Personne ne se lève." },
      { with: "tibere", text: "Tibère a un œil qui gonfle. Il compte les besaces deux fois, à voix haute, et annonce le compte comme on annonce une perte au jeu." },
      "Ce qui reste suffira peut-être. Tu n'en sais rien.",
    ],
    fx: { flag: "vf:or_ampute" },
    choices: [{ label: "Reprendre la route de Salvèze", to: "VF_rep_port" }] },

  VF_rep_port: { act: "V", title: "La Monnaie", place: "changeurs",
    text: [
      "Au port aux Sauniers, le Guet t'attend avec deux charrettes et vingt gardes. On charge l'or sous les yeux de la foule, et on le conduit à la Monnaie, sur l'île des Changeurs, entre deux rangs de hallebardes. Des gamins courent derrière les charrettes en criant le nom de la reine.",
      "Dans la grande salle de la Monnaie, les essayeurs de la République attendent derrière leurs balances. On pose les lingots un à un sur le plateau. Le maître essayeur pèse, touche à la pierre, inscrit. Un commis en noir, que tu as vu chez Corisande Marrel, lui tend les poids.",
      "Les poids {{pie#vf_rep_poids|sont des poids de bronze de la République, marqués de la tour|sont creusés par-dessous et bouchés de liège : chaque lingot pèsera un dixième de moins sur le registre que dans la main}}.",
    ],
    choices: [
      { label: "Retourner un des poids devant le maître essayeur", hide: { not: { voile: "vf_rep_poids" } }, fx: { flag: "vf:poids_faux", fac: { banque: -10, conseil: 5 }, ep: ["perso", 1200] }, to: "VF_rep_conseil" },
      { label: "Laisser peser, et suivre les charrettes au Conseil", to: "VF_rep_conseil" },
    ] },

  VF_rep_conseil: { act: "V", title: "Ce que tu demandes", place: "beffroi",
    text: [
      "Le Conseil des Comptoirs siège le soir même. Les quarante maisons votent à l'unanimité le paiement du duc d'Aveline, puis un remerciement solennel à {hero}, chercheur de choses perdues du quai des Lanternes. On t'appelle à la tribune. Le prévôt te demande ce que la République peut faire pour toi.",
      { if: { has: "vf:poids_faux" }, text: "Les poids creux sont posés sur la table du Conseil, comme des pièces à conviction. Personne ne les regarde." },
      "Maître Vernier se penche vers son voisin, assez fort pour que tu l'entendes. « {{oreille#vf_rep_vernier|Qu'il demande, la ville est reconnaissante|Qu'il demande vite, avant de comprendre ce qu'il pourrait demander}} », dit-il.",
      { if: { not: { has: "prevot:dejoue" } }, text: "Haumont Delisle préside, souriant. Il t'a applaudi{e} le premier." },
    ],
    choices: [
      { label: "Le grain des Halles, distribué cet hiver aux quartiers bas", fx: { set: { vf_demande: "grain" }, fac: { hautes: 5 } }, to: "VF_rep_amaury" },
      { label: "Un siège au Conseil pour les gens des Hautes-Eaux", fx: { set: { vf_demande: "siege" }, fac: { hautes: 15, conseil: -5 } }, to: "VF_rep_amaury" },
      { label: "L'amnistie de tous les émeutiers de la faim", fx: { set: { vf_demande: "amnistie" } }, to: "VF_rep_amaury" },
      { label: "Ce qu'ils pensent tout bas : le dixième de l'or, pour toi", hide: { not: { voile: "vf_rep_vernier" } }, fx: { set: { vf_demande: "dixieme" }, gold: 10000 }, to: "VF_rep_amaury" },
      { label: "Rien", fx: { set: { vf_demande: "rien" } }, to: "VF_rep_amaury" },
    ] },

  VF_rep_amaury: { act: "V", title: "La porte des Sauniers", place: "salveze",
    text: [
      "On livre l'or au duc à la porte des Sauniers, un matin de mai, sous un dais de toile bleue. Amaury de Sauveterre compte lui-même, assis à une table de camp, une plume derrière l'oreille.",
      { if: { all: [PLEIN, { not: { has: "vf:or_ampute" } }] }, text: "Le compte tombe juste à la Saint-Jean. Quatre millions, et un reste, qu'Amaury fait reporter au crédit de la ville avec une courtoisie de banquier." },
      { if: { any: [PARTIE, { has: "vf:or_ampute" }] }, text: "Le compte n'y est pas. Amaury note le manque, le regarde longtemps, puis accepte le reste en sel des Hautes-Eaux, sur dix ans. « Le duc aime le sel, dit-il. Il le mange avec tout. »" },
      { if: { not: { has: "prevot:dejoue" } }, text: "Avant de partir, il te prend à part et te met dans la main une liasse de lettres nouée d'un ruban bleu. « Le prévôt m'a écrit beaucoup, dit-il. Le duc est payé, il n'a plus besoin de traîtres. Faites-en ce que vous voudrez. » Ce sont les lettres de Delisle." },
      { if: { has: "ivm:duc_saintjean" }, text: "« Sur la route, le jour où j'ai quitté la ville, je vous ai dit que le duc viendrait avec ses piques s'il n'était pas payé, ajoute-t-il. Vous l'avez entendu, je crois. Il restera chez lui. »" },
      "« Vous m'avez coûté une ville, dit-il en remontant à cheval. {{oreille#vf_rep_amaury_adieu|Je ne vous en veux pas|J'en suis soulagé, je n'aimais pas l'idée de la gouverner}}. »",
    ],
    fx: { flag: "vf:duc_paye" },
    choices: [
      { label: "Porter les lettres de Delisle au Conseil", hide: { has: "prevot:dejoue" }, fx: { flag: ["vf:lettres_delisle", "vf:prevot_juge"], fac: { conseil: 10 } }, to: "VF_rep_corisande" },
      { label: "Aller voir Corisande Marrel", to: "VF_rep_corisande" },
    ] },

  VF_rep_corisande: { act: "V", title: "La Banque debout", place: "changeurs",
    text: [
      { if: { has: "vf:lettres_delisle" }, text: "Haumont Delisle est arrêté le soir même, au Conseil, pendant qu'on lit ses lettres à voix haute. En silence, il retire lui-même sa chaîne et la pose sur la table." },
      "La Banque Marrel a rouvert ses grilles. La dette de la République est payée, et la Banque qui la portait est debout. Ses titres sur les Hautes-Eaux aussi : personne ne les a lus devant le peuple.",
      "Corisande Marrel te reçoit dans la salle des comptes, derrière son grand registre. « Vous avez sauvé ma maison, dit-elle. {{oreille#vf_rep_cori|Je vous en suis obligée|Je vous en veux de me l'avoir sauvée sans me la demander, et de garder la Charte quelque part où je ne peux pas la trouver}}. »",
      { if: { has: "vf:poids_faux" }, text: "« Le commis aux poids, ajoute-t-elle, a été renvoyé. Il agissait seul, naturellement. » Elle le dit sans changer de voix." },
    ],
    choices: [{ label: "Rentrer aux Joncs-Bas", to: "VF_rep_joncs" }] },

  VF_rep_joncs: { act: "V", title: "Sous le plancher", place: "joncs",
    text: [
      "Aux Joncs-Bas, rien n'a changé. Les filets sèchent entre les pilotis, les dentellières travaillent sur les pontons, et l'intendant des Fourcaud passe le premier lundi du mois prendre le cens des bassins. On le paie, comme avant.",
      { if: { is: { vf_charte_a: "joncs" } }, text: "Tu remets l'étui de cuir à Mère Ancolie, de ta main à la sienne. Elle le garde sur ses genoux toute la soirée, ses doigts sur la cire du sceau, comme on garde la main d'un malade." },
      "Sous le plancher de la maison d'Ancolie, entre deux pilotis, il y a un coffre de cèdre que l'eau ne pourrit pas. La Charte y entre la nuit même, avec le Registre. On replace les planches. Une petite fille balaie le sel par-dessus.",
      { if: { has: "vt:carte_terres" }, text: "La carte de la mosaïque entre dans le coffre avec eux, roulée dans sa soie violette. Les noms y attendront aussi." },
      { if: { not: { has: "iit:ancolie_blessee" } }, text: "« {{oreille#vf_rep_ancolie|Nous attendrons|Nous attendrons encore cent ans, et c'est toi qui nous l'as demandé, et je ne sais pas si je te remercie}} », dit Mère Ancolie." },
      { if: { has: "vt:avis_lison_toi" }, with: "lison", text: "Pour le retour, Lison t'a gardé une place dans sa barque, à côté d'elle. Elle a poussé ses filets pour la faire." },
      { with: "lison", text: "Lison s'assied sur le plancher, juste au-dessus du coffre, et y reste." },
    ],
    choices: [{ label: "Revenir en ville pour la fête de la Saint-Jean", to: "VF_rep_fete" }] },

  VF_rep_fete: { act: "V", title: "La Saint-Jean", place: "beffroi",
    text: [
      "À la Saint-Jean, Salvèze danse sur la place du Beffroi. On a allumé des feux sur les ponts. Le Conseil donne du vin aux fontaines, la Banque donne des oublies, et les soldats du Guet dansent avec leurs hallebardes posées contre les arcades.",
      { if: { is: { vf_demande: "grain" } }, text: "Sur les marches des Halles, on distribue du pain blanc aux gens des quartiers bas. Le grain est celui que tu as demandé. Les boulangers ont reçu ordre de ne pas dire d'où il vient. Ils le disent quand même." },
      { if: { is: { vf_demande: "siege" } }, text: "Sur le banc du Conseil, à la place de la maison Delisle, une femme des Hautes-Eaux s'est assise pour la première fois, une saunière aux mains crevassées. Les autres maisons l'ignorent. Elle s'en moque. Elle vote." },
      { if: { is: { vf_demande: "amnistie" } }, text: "On a ouvert les portes de la Tour Ronde. Les émeutiers de la faim sont sortis un à un, en clignant des yeux, et leurs mères les attendaient sur le pont." },
      { if: { is: { vf_demande: "dixieme" } }, text: "Tu as dans tes coffres le dixième de l'or de la reine, voté par le Conseil, à l'unanimité moins une voix. Personne ne t'en parle. Tout le monde le sait." },
      { if: { is: { vf_demande: "rien" } }, text: "Le Conseil t'a fait remettre une médaille d'or, pour la forme, puisque tu n'as rien demandé." },
    ],
    fx: { item: "vf_tr_medaille", clock: { tresors: 1 }, flag: "tresor:vf_medaille" },
    choices: [{ label: "Descendre au quai, à la nuit", big: true, to: "VF_rep_fin" }] },

  VF_rep_fin: { act: "V", title: "L'or de la République", place: "quai", end: true, epilogue: true, fx: END("republique"),
    text: [
      "La nuit de la Saint-Jean, le quai des Lanternes est plein de gens qui ne savent pas danser et qui boivent pour se donner du courage. Tu t'assieds sur les trois marches de la boutique Carrus. D'ici, on entend la musique de la place, de loin, par-dessus les toits.",
      { if: CORNET, text: "Tu as le cornet d'os à l'oreille. Les passants te saluent, et leurs mots tremblent." },
      "Un saunier de Grisemotte s'arrête devant toi, un peu ivre. « {{oreille|Merci pour la ville|Merci pour la ville, et j'aurai payé le cens aux Fourcaud jusqu'à ma mort, et mes fils après moi}} », dit-il. Un commis de la Banque, plus loin, lève son verre vers toi. « {{oreille|À la République|À la Banque, qui vous doit tout et ne vous le rendra jamais}} », dit-il.",
      { if: { has: "vf:parts_payees" }, text: "Les rameurs de la traversée boivent ta santé à la table voisine, chacun sa part cousue dans sa ceinture. Ils la boivent fort." },
      { if: { has: "vf:parts_promises" }, text: "Les rameurs de la traversée t'attendent au bas des marches. Le Conseil a voté leurs parts ce matin, comme tu l'avais promis au milieu de la mer. Ils sont venus te le dire." },
      { if: { has: "vf:riwal_dejoue" }, text: "Les huit hommes de Riwal sont venus à la fête sans lui. Le plus jeune te fait un signe de tête, de loin, en levant sa chope." },
      { if: { has: "tresor:vf_medaille" }, text: "La médaille d'or du Conseil est au fond de ta poche. Un gamin te la demande pour la voir, la mord, et te la rend." },
      { with: "tibere", text: "Tibère s'assied à côté de toi avec deux chopes. « {{oreille#vf_rep_tibere|Bonne affaire, tout compte fait|Rosalie m'a parlé ce matin, trois phrases, et la troisième était merci}} », dit-il." },
      { with: "lison", text: "Lison est debout contre le mur, les bras croisés. « {{oreille#vf_rep_lison_fin|C'était juste, je suppose|Tu as choisi la ville, et je te comprends, et je rentre aux Joncs demain}} », dit-elle." },
      { with: "salome", text: "Salomé a mis sa veste propre. « La mer a rendu de l'or, dit-elle. C'est la première fois que je la vois rendre quelque chose. »" },
      { with: "fauvette", text: "Fauvette compte les feux sur les ponts, puis les poches des danseurs, par habitude. « {{oreille|Ils dansent mal|Je n'ai jamais dansé, apprends-moi, et ne ris pas}} », dit-elle." },
      { with: "gildas", text: "Frère Gildas regarde la musique de loin. « La Charte est sous un plancher, dit-il. Elle a déjà connu pire. Elle attendra. »" },
      "Tu regardes la ville qui danse, debout, sauvée, injuste comme avant. Tu {{miroir#vf_rep_dernier|as fait le choix le plus sage|as aimé qu'on t'applaudisse au Conseil, et tu sais que les sauniers de Grisemotte paieront le cens aux Fourcaud cent ans encore}}.",
    ] },
});

// ==================================================================== VF_banque: Corisande's bargain
Object.assign(P, {
  VF_banque: { act: "V", title: "La Constance", place: "sorne",
    fx: { ep: ["seance", 2000] },
    text: [
      "*La Constance* est mouillée à deux encablures de la tour, ses fanaux encore allumés dans le jour levé. Une chaloupe peinte en noir s'en détache et vient se ranger au pied de l'échelle. Corisande Marrel est assise à la poupe, sa canne d'ébène en travers des genoux, sa robe de deuil serrée contre le vent. Tu descends jusqu'à elle.",
      "Elle regarde l'or qu'on charge, puis toi. « Le marché tient, dit-elle. L'or à la Banque, qui paiera le duc. Le Registre et la Charte à moi, qui les brûlerai. Vous, riche, et libre de tout ce qu'on vous reproche. {{oreille#vf_ba_cori|Je tiens toujours parole|Je tiens toujours parole, et je vous ferai surveiller jusqu'à votre mort, parce que vous avez lu ce que vous allez brûler}}. »",
      { if: PLOMB, text: "Un de ses commis plonge la main dans ta besace, mord une pièce, et se penche à l'oreille de sa maîtresse. Corisande garde son sérieux. « Le plomb aussi, dit-elle. Vous apprendrez à trier. Les coffres de la Banque s'en chargeront. »" },
      { with: "lison", text: "Lison s'est mise entre toi et la chaloupe. « {{oreille#vf_ba_lison|Fais ce que tu veux|Si tu lui donnes, je ne te connais plus, et je ne pourrai pas faire autrement}} », dit-elle." },
      { with: "salome", text: "Salomé regarde la bannière noire aux besants d'or, à la poupe de *La Constance*. C'est la même que sur la barque qui accompagnait Maïwenn, le dernier matin. Elle se tait et ramasse son sac." },
      { with: "gildas", text: "Frère Gildas fait un pas vers Corisande, les mains sorties de ses manches. Deux marins posent la main sur leur épée. Il s'arrête et te regarde, toi seul{e}." },
    ],
    choices: [
      { label: "Donner l'étui de la Charte et les feuillets du Registre", big: true, to: "VF_ba_constance" },
      { label: "Les donner, mais glisser un feuillet dans ta botte avant", test: { dom: "discretion", diff: -20, label: "Garder un feuillet", help: [FAU, { if: { has: "metier:mains" }, v: 15 }] },
        win: { fx: { flag: "vf:feuillet_garde" }, to: "VF_ba_constance" }, lose: { fx: { flag: "vf:feuillet_vu" }, to: "VF_ba_constance" } },
    ] },

  VF_ba_constance: { act: "V", title: "Le contrat", place: null,
    text: [
      { with: "lison", text: "Lison reste à l'écart de la chaloupe. Quand tu te retournes, elle est déjà dans la barque des Joncs, à l'aviron, le dos tourné." },
      { with: "salome", text: "Salomé remonte sur sa propre barque et lève l'ancre sans attendre personne." },
      { with: "gildas", text: "Frère Gildas reste sur la plate-forme de la tour, debout, sa bure claquant au vent. Il descend le dernier, dans la barque des Joncs, les yeux ailleurs." },
      { with: "tibere", text: "Tibère, lui, monte sur la chaloupe derrière toi, sans un mot. Il s'assied sur le banc, les mains sur les cuisses, et regarde ses bottes." },
      { with: "fauvette", text: "Fauvette monte aussi. Elle examine les cordages de *La Constance* comme on examine les gouttières d'un hôtel avant d'y entrer de nuit." },
      "Dans la cabine de poupe, sur une table vissée au plancher, un contrat t'attend, déjà écrit, en double. Corisande le signe la première, d'une plume qui ne crache pas. *{{loupe#vf_ba_clause|Moyennant quoi la Banque Marrel reconnaît au chercheur du quai des Lanternes la propriété d'un hôtel sur l'île des Changeurs et une rente de mille ducats l'an|Et si ledit chercheur vient jamais à parler de ce qu'il a lu, la rente cesse, et la Banque reprend sur sa personne la créance d'Odeline Carrus, avec les intérêts depuis le jour de sa mort}}.*",
      { if: { has: "vf:feuillet_vu" }, text: "Avant de signer, Corisande tend la main, paume ouverte, sans te regarder. Tu retires le feuillet de ta botte et tu le poses dedans. Elle le range avec les autres." },
    ],
    choices: [
      { label: "Exiger qu'on raye la clause écrite à l'encre cachée", hide: { not: { voile: "vf_ba_clause" } }, fx: { flag: "vf:clause_rayee", ep: ["perso", 1200] }, to: "VF_ba_brasier" },
      { label: "Signer", to: "VF_ba_brasier" },
    ] },

  VF_ba_brasier: { act: "V", title: "Le four de la Monnaie", place: "changeurs",
    text: [
      { if: { has: "vf:clause_rayee" }, text: "Corisande a rayé la clause de sa main, sans discuter, d'un seul trait. « Vous avez de bons yeux, a-t-elle dit. Je l'aurais fait aussi. »" },
      "Le four de la Monnaie est au fond d'une cour pavée, sous une hotte de briques noires. On y fond les vieilles pièces. Ce soir, le maître fondeur a reçu congé, et c'est Corisande Marrel qui tient le tisonnier.",
      "La cour {{echo#vf_ba_four|est chaude et sent le charbon|garde, sous le ronflement du four, la voix d'un fondeur d'il y a trois siècles : « Les actes de la reine aussi ? Tous ? Alors qu'on paie double, Messieurs, ça ne brûle pas bien, le vélin »}}.",
      "Elle brûle les feuillets un à un. Le vélin se tord, noircit sur les bords, et l'écriture des Taiseurs reste lisible un instant dans la braise, blanche sur noir, avant de tomber. Puis elle tend la main vers l'étui de la Charte.",
      { if: { any: [LIBRE, { has: "lothaire:allie" }] }, text: "Lothaire Brunel se tient dans l'ombre de la hotte, ses gants gris à la main. Il te regarde. « Vous pensez à la jeter vous-même, dit-il doucement. Pour pouvoir dire que vous l'avez fait. »" },
    ],
    choices: [
      { label: "Jeter la Charte au feu toi-même", fx: { flag: "vf:charte_jetee" }, to: "VF_ba_cendres" },
      { label: "La lui tendre, et la regarder faire", to: "VF_ba_cendres" },
    ] },

  VF_ba_cendres: { act: "V", title: "Les cendres", place: "changeurs",
    text: [
      { if: { has: "vf:charte_jetee" }, text: "Tu ouvres l'étui et tu jettes la Charte dans la gueule du four. La cire verte fond d'abord, et coule, et prend feu avec une flamme bleue. Le reste brûle vite.", else: "Corisande ouvre l'étui, déroule la Charte, la regarde un moment à la lumière du feu. Puis elle la pose sur les braises, à plat, comme on couche un enfant. La cire verte fond, et prend feu avec une flamme bleue." },
      "Quand il ne reste plus rien, elle fait balayer les cendres dans un seau, et un commis va le vider dans la Salve, depuis le pont des Changeurs. Le courant les emporte vers la mer. Elles y retournent.",
      { if: { has: "vf:feuillet_garde" }, text: "Dans ta botte, contre ta cheville, le feuillet que tu as gardé est encore tiède de ta peau." },
      "Le lendemain, un notaire de la Banque t'apporte les clés d'un hôtel, rue des Lombards, et une lettre de crédit sur trois maisons de banque étrangères.",
    ],
    fx: { gold: 20000, ep: ["perso", 1000] },
    choices: [{ label: "Voir ce que l'or de la reine achète", to: "VF_ba_duc" }] },

  VF_ba_duc: { act: "V", title: "La paix achetée", place: "salveze",
    text: [
      "L'or de la reine part pour Aveline à la Saint-Jean, frappé de neuf aux armes de la Banque Marrel. Amaury de Sauveterre compte les sacs à la porte des Sauniers, signe le reçu, et lève le camp le soir même. Les bannières bleues repassent la frontière sans avoir vu le Beffroi.",
      "La République est sauvée, et elle doit son salut à la Banque. Le Conseil des Comptoirs vote des remerciements à Madame Marrel, et une statue, qu'elle refuse.",
      { if: { not: { has: "prevot:dejoue" } }, text: "Haumont Delisle préside la séance. Il remercie la Banque avec émotion. Corisande Marrel a ses lettres au duc dans un tiroir de son bureau, et il le sait. Il présidera le Conseil jusqu'à sa mort, comme elle voudra." },
      { if: { has: "prevot:dejoue" }, text: "Le nouveau prévôt est un cousin des Marrel. Il a été élu à l'unanimité moins trois voix." },
      "Dans les Hautes-Eaux, les intendants des Fourcaud et des Vernier font le tour des salines avec les titres de la Banque, renouvelés et recopiés au propre sur du vélin neuf.",
    ],
    choices: [{ label: "Prendre possession de l'hôtel de la rue des Lombards", to: "VF_ba_hotel" }] },

  VF_ba_hotel: { act: "V", title: "L'hôtel de la rue des Lombards", place: "changeurs",
    text: [
      "L'hôtel a quatre étages, une cour carrée, une écurie, un puits à margelle sculptée et onze domestiques qu'on t'a choisis. L'intendant s'appelle Maître Achard. Il te fait visiter en marchant un pas derrière toi.",
      "Dans la grande salle, il te montre une tapisserie qui couvre tout un mur : la reine Ysaure à cheval, avec sa cour, à la chasse au héron. La tapisserie {{pie#vf_ba_tapisserie|est une pièce d'Arras ancienne, d'un prix énorme|est une copie récente, tissée à Salvèze pour la Banque, et on a cousu dans la doublure, à hauteur d'homme, une poche où loge un cornet d'écoute tourné vers ta chambre}}.",
      { with: "tibere", text: "Tibère fait le tour de la cour, tâte les murs, compte les portes. « Une bonne maison, dit-il. On y entre par trois côtés. On en sort par un seul. »" },
    ],
    choices: [
      { label: "Décrocher la tapisserie et arracher la poche de la doublure", hide: { not: { voile: "vf_ba_tapisserie" } }, fx: { flag: "vf:ecoute_arrachee", ep: ["perso", 800] }, to: "VF_ba_diner" },
      { label: "Donner ton premier dîner", to: "VF_ba_diner" },
    ] },

  VF_ba_diner: { act: "V", title: "Les nouveaux amis", place: "changeurs",
    takes: "evening",
    text: [
      "Ton premier dîner réunit douze convives, choisis par Maître Achard : des héritiers de maisons, un chanoine, un poète, deux veuves riches, le jeune Fourcaud. On sert un brochet de la Salve farci aux amandes, et du vin des Combes que tu ne savais pas si bon.",
      { if: CORNET, text: "Tu as gardé le cornet d'os. Tu le portes à l'oreille, comme on se gratte la tempe, en levant ton verre." },
      "Le jeune Fourcaud lève le sien. « {{oreille|À notre hôte, qui a sauvé la République|À notre hôte, qui sera ruiné dans dix ans, comme tous les parvenus}} », dit-il. Une des veuves pose la main sur ton bras. « {{oreille|Vous devez nous raconter Sorne|Je veux savoir combien il vous en reste, et si quelqu'un partage votre lit}} », dit-elle. Le chanoine, à ta droite : « {{oreille|Dieu récompense les justes|J'ai lu votre nom sur la liste de la Banque l'an dernier, au mandat d'arrêt, et je m'en souviens}}. »",
      "Le poète récite un sonnet sur la reine Ysaure, morte d'amour pour son peuple. « {{oreille#vf_ba_poete|C'est la plus belle histoire de Salvèze|C'est Madame Marrel qui m'a payé pour l'écrire, et qui a choisi les rimes}} », dit-il en se rasseyant.",
    ],
    choices: [
      { label: "Ranger le cornet dans sa boîte, et ne plus l'en sortir", fx: { flag: "vf:cornet_range" }, to: "VF_ba_cabinet" },
      { label: "Continuer d'écouter jusqu'au dessert", to: "VF_ba_cabinet" },
    ] },

  VF_ba_cabinet: { act: "V", title: "Les gants gris", place: "changeurs",
    text: [
      "Au mois de juin, Corisande Marrel te fait appeler. Elle te propose une charge : chercheur de la Banque, avec un cabinet, deux commis et le droit d'ouvrir n'importe quelle archive de la République.",
      { if: LIBRE, text: "Lothaire Brunel est dans le cabinet quand tu y entres. Il est en train de vider ses tiroirs dans une caisse. Il te tend une paire de gants gris, neufs, dans une boîte. « Vous dites merci, dit-il sans lever les yeux. Vous pensez que vous ne deviendrez jamais comme moi. Nous verrons. » Il met son cornet jumeau dans sa poche et s'en va." },
      { if: { has: "lothaire:allie" }, text: "Lothaire Brunel vient te voir le premier jour. Il a trahi la Banque pour toi, et tu as tout rendu à la Banque. Il s'assied en face de toi, les gants à la main. « Vous dites que vous n'aviez pas le choix, dit-il. Vous pensez que vous l'aviez. C'est la même chose que moi, il y a vingt ans. » Il part le soir même pour le nord." },
      { if: { any: [{ has: "lothaire:mort" }, { all: [{ has: "lothaire:vaincu" }, { not: { has: "lothaire:allie" } }] }] }, text: "Le cabinet de Lothaire Brunel est resté tel qu'il l'a laissé : les cartes, les clés, les cornets de toutes tailles. Dans le tiroir du bureau, une paire de gants gris, neufs, dans leur boîte. Les commis te regardent les prendre." },
      { if: { all: [{ has: "lothaire:allie" }, { has: "vt:avis_lothaire" }] }, text: "« Vous l'avez vendue, dit Lothaire avant de partir. J'avais raison sur vous. Je n'en suis pas content. »" },
      "Sur le bureau, le registre du chercheur est ouvert à la dernière page. *{{loupe#vf_ba_registre|Affaires en cours : néant|Affaires en cours : surveiller le nouveau chercheur, ses visites, ses lettres, ses amis des marais ; rapport chaque samedi à Madame}}.*",
    ],
    choices: [
      { label: "Accepter la charge", fx: { flag: "vf:chercheur_banque", fac: { banque: 10 } }, to: "VF_ba_joncs" },
      { label: "Refuser poliment, et garder ta rente", to: "VF_ba_joncs" },
    ] },

  VF_ba_joncs: { act: "V", title: "Les nouvelles des marais", place: "changeurs",
    text: [
      "En septembre, une lettre arrive des Hautes-Eaux, sans signature, d'une écriture de dentellière, tout en boucles serrées. Elle dit qu'aux Joncs-Bas, l'intendant des Fourcaud a doublé le cens des bassins, et que ceux qui ne paient pas sont mis hors de leurs maisons, qui sont sur des pilotis, et qu'on démonte.",
      "*{{loupe#vf_ba_lettre|Nous vous souhaitons bonne santé dans votre maison neuve|Nous savons ce que tu as fait, et nous ne t'en voulons pas autant que nous le voudrions : ta mère était des nôtres}}.*",
    ],
    choices: [
      { label: "Envoyer chaque mois, sans signer, de quoi payer le cens de dix familles", fx: { flag: "vf:cens_paye", gold: -4000, fac: { hautes: 10 } }, to: "VF_ba_visite" },
      { label: "Descendre aux Joncs-Bas, toi-même", to: "VF_ba_visite" },
      { label: "Brûler la lettre", fx: { flag: "vf:lettre_brulee" }, to: "VF_ba_quai" },
    ] },

  VF_ba_visite: { act: "V", title: "Les Joncs-Bas", place: "joncs",
    text: [
      "Tu descends aux Joncs-Bas dans une barque de louage, avec un manteau de drap fin que tu regrettes dès la première vasière. Sur les pontons, les dentellières lèvent la tête, te reconnaissent, et la baissent.",
      { if: { not: { has: "iit:ancolie_blessee" } }, text: "Mère Ancolie te reçoit sur le seuil, sans te faire entrer. Elle tourne la tête vers toi. « {{oreille#vf_ba_ancolie|Tu es toujours la bienvenue ici|Tu as brûlé la parole de la reine, et je t'aime encore, parce que ta mère était des nôtres, et je ne me le pardonne pas}} », dit-elle." },
      { if: { has: "iit:ancolie_blessee" }, text: "La maison de Mère Ancolie est fermée. Elle est morte l'été dernier. Une dentellière te montre sa tombe, sur le tertre, et repart sans attendre que tu aies fini de regarder." },
      { if: { has: "vf:cens_paye" }, text: "Dix familles n'ont pas été mises dehors. Elles ignorent pourquoi. Elles se doutent." },
    ],
    choices: [{ label: "Rentrer en ville", to: "VF_ba_quai" }] },

  VF_ba_quai: { act: "V", title: "La boutique fermée", place: "quai",
    takes: "night",
    text: [
      "Tu as racheté la boutique Carrus aux créanciers d'Odeline, pour trois fois son prix. Elle est fermée. Les volets sont cloués. Une nuit d'hiver, tu y descends seul{e}, avec une lanterne sourde et la clé.",
      "La poussière est la même. Les étagères sont vides. L'escalier de la cave est toujours aussi raide.",
      { if: { has: "vf:lettre_brulee" }, text: "Tu as brûlé la lettre des Joncs-Bas sans y répondre. Ici, dans le noir, les boucles serrées de son écriture te reviennent une à une." },
      "La boutique {{echo#vf_ba_boutique|est froide et silencieuse|garde la voix d'Odeline, la dernière fois qu'elle t'a parlé de l'argent : « Je vends ce secret pour toi, pour que tu n'aies jamais à faire ce que je fais. Tu me remercieras quand tu seras riche »}}.",
    ],
    choices: [{ label: "Remonter dans ta maison neuve", big: true, to: "VF_ba_fin" }] },

  VF_ba_fin: { act: "V", title: "Le marché de Corisande", place: "changeurs", end: true, epilogue: true, fx: END("banque"),
    text: [
      "Les années passent rue des Lombards. Tu dînes, tu prêtes, tu fais bâtir. On t'invite au Conseil, aux mariages des maisons, aux enterrements. Corisande Marrel te salue d'un signe de tête, à la messe, chaque dimanche, et chaque samedi un commis lui porte un rapport sur toi.",
      { if: { not: { has: "vf:cornet_range" } }, text: "Tu portes toujours le cornet d'os, par habitude, dans la poche de ton pourpoint. Aux dîners, tu le portes à l'oreille. Les phrases de tes amis tremblent toutes, une à une, sans exception, comme les feuilles d'un peuplier." },
      { if: { has: "vf:cornet_range" }, text: "Le cornet d'os dort dans sa boîte, au fond d'un coffre. Il y reste. Tu lis sur les visages, à la place, et tu te trompes moins souvent qu'avant." },
      "« {{oreille|Vous êtes notre meilleur ami|Vous êtes notre meilleur placement}} », te dit le jeune Fourcaud, un soir de fête. « {{oreille|Je ne regrette rien|Je regrette la Charte chaque nuit, et chaque matin je recompte mes coffres}} », te dit Corisande Marrel, l'hiver de sa mort, en te serrant la main.",
      { if: { has: "vf:chercheur_banque" }, text: "Tu tiens le cabinet du chercheur de la Banque, celui de Lothaire Brunel. Tu ouvres pour Madame Marrel les archives de la République, et tu y trouves surtout ce qu'elle t'envoie y chercher." },
      { if: { has: "vf:ecoute_arrachee" }, text: "La tapisserie de la reine a retrouvé son mur, recousue, sans sa poche. Dans ta grande salle, on parle à voix ordinaire, et tu sais ce que cela vaut." },
      { with: "tibere", text: "Tibère loge au-dessus de ton écurie. Il est devenu ton intendant, puis ton ami, puis les deux. « {{oreille#vf_ba_tibere|C'est une bonne place|C'est une bonne place, et je reconnais la cage, j'y ai vécu cinq ans à cinq ducats la semaine}} », dit-il." },
      { with: "fauvette", text: "Fauvette vient dîner le dimanche. Elle repart avec une cuillère d'argent chaque fois. Tu la laisses faire. C'est la seule chose honnête à ta table." },
      { after: "voile:vf_ba_registre", text: "Chaque samedi, à la troisième heure, un commis de la Banque passe dans ta rue. Il t'arrive de laisser sur ta fenêtre une lettre écrite pour lui, pleine de choses fausses et vraisemblables." },
      { if: { has: "vf:feuillet_garde" }, text: "Le feuillet que tu as gardé est cousu dans la doublure de ton manteau d'hiver. Tu ne l'as jamais relu. Tu le sens contre ton côté quand il fait froid." },
      { if: { is: { ivm_charte: "silence" } }, text: "Devant Mère Ancolie, avant la Grande Basse, tu avais gardé le silence quand elle t'avait demandé ce que tu ferais de la Charte. Elle avait souri. Tu te demandes parfois ce qu'elle avait entendu dans ce silence." },
      "Le soir, dans la grande salle, sous la tapisserie de la reine à la chasse, tu comptes ce que tu as. Tu {{miroir#vf_ba_miroir|as eu raison, la ville n'a pas eu faim|as vendu la parole d'une reine pour ne plus jamais avoir peur de manquer, comme Odeline a voulu vendre la sienne pour toi, et tu as réussi là où elle a échoué}}.",
    ] },
});

// ==================================================================== VF_silence: the new Keeper
Object.assign(P, {
  VF_silence: { act: "V", title: "Tout rendre", place: "sorne",
    fx: { ep: ["seance", 2000] },
    text: [
      "Sur la plate-forme de la tour de la Reine, tu défais la toile cirée. Tu remets les feuillets du Registre dans l'étui de la Charte, un à un, dans l'ordre, et tu fermes l'étui. Puis tu demandes un plomb de sonde et de la corde.",
      { if: OR, text: "Tu fais ramener l'or au bord du parapet. Les besaces, les coffres, tout ce qu'on a hissé de la salle avec tant de peine. Personne ne discute. On les aligne contre la pierre, face à la mer." },
      "Tu as prêté serment aux Joncs-Bas, la nuit de la tempête. Tu en comprends les mots pour la première fois, ici, au-dessus de l'eau qui recouvre la salle : *Ce qui a été tu sera gardé. Ce qui sera gardé ne sera pas vendu.*",
      { with: "gildas", text: "Frère Gildas s'approche. Il défait, sous sa bure, un cordon de lin noir à sept nœuds, qu'il porte au cou depuis trente ans, et il te le passe par-dessus la tête. « Le Gardien le porte, dit-il. Moi, j'ai fini. » Ses mains ne tremblent pas. C'est toi qui trembles." },
      { without: "gildas", text: "Tu penses à Frère Gildas, qui a gardé ce silence trente ans, et à ce que ce silence a coûté à Odeline. Tu penses que quelqu'un, maintenant, va devoir le garder autrement." },
      { with: "lison", text: "Lison te regarde faire sans bouger, adossée au parapet. « {{oreille#vf_si_lison|Ma grand-mère aurait fait pareil|Je croyais que l'or t'intéressait, comme tous les autres, et je me suis trompée, et j'en suis heureuse à pleurer}} », dit-elle." },
    ],
    choices: [{ label: "Lester l'étui et poser la main dessus une dernière fois", big: true, to: "VF_si_rendre" }] },

  VF_si_rendre: { act: "V", title: "La voix de la tour", place: "sorne",
    text: [
      "Tu noues le plomb de sonde à l'étui, et la corde au plomb. Tu poses la main à plat sur le cuir. Sous la tour, la mer est verte et calme, et quelque part au fond de ce vert il y a la salle, le lutrin, les dalles.",
      { if: { has: "vt:charte_lue_tour" }, text: "Tu l'as lue une fois, à voix haute, du haut de cette tour. Ceux qui l'ont entendue s'en souviendront. Cela suffira peut-être." },
      { if: OR, text: "L'or, contre le parapet, {{pie#vf_si_or|vaut la rançon d'une ville|vaut une guerre, deux procès, trois meurtres et la ruine des Joncs-Bas, et il le vaudra encore dans trois cents ans}}. On le pousse par-dessus bord, coffre après coffre, besace après besace. Chaque fois, la mer fait un bruit sourd, et se referme." },
      "La pierre de la tour {{echo#vf_si_salle|est tiède de soleil et sent le sel|rend la voix d'Aymeric Vasse, le chancelier, le jour où il a monté ces marches pour la dernière fois : « Celui qui viendra et qui laissera tout, c'est à lui que nous la confions. Les autres, la mer les jugera »}}.",
      { after: "voile:vf_si_salle", text: "Tu restes un moment immobile, la main sur l'étui. Celui qui laissera tout." },
      "Tu laisses filer la corde entre tes doigts. L'étui descend, tourne sur lui-même, devient une ombre, puis rien. Quand la corde se détend, tu la coupes, et tu lâches le bout.",
    ],
    choices: [{ label: "Descendre de la tour", big: true, to: "VF_si_remontee" }] },

  VF_si_remontee: { act: "V", title: "Ceux qui voulaient l'or", place: "sorne",
    text: [
      "Au pied de la tour, les barques t'attendent. Tes gens ont tout vu, du bas de l'échelle : l'étui qui descend, et l'or qui tombe dans la mer.",
      { if: { has: "ivm:part_ecumeurs" }, text: "Riwal s'est levé dans sa barque, au milieu de ses huit hommes, les grappins déjà à la main. « Un dixième, dit-il. De rien, ça fait rien. {{oreille#vf_si_riwal|On va plonger le chercher nous-mêmes|On va plonger, et si tu te mets en travers, la mer trouvera ton corps avant le soir}}. »" },
      { if: { all: [{ not: { has: "ivm:part_ecumeurs" } }, { has: "basse:equipage" }] }, text: "Tes rameurs se sont levés sur les bancs. Le plus fort, un débardeur du port, retire déjà sa chemise. « On a ramé pour rien, dit-il. Il y a dix brasses, pas plus. Rien qu'un coffre. » Les autres approuvent de la tête." },
      { if: { not: { has: "basse:equipage" } }, text: "Tes compagnons te regardent descendre les mains vides. Plus loin, une barque de pêcheurs de Port-Vasier, qui suivait la vôtre depuis la nuit, s'approche à la rame de l'endroit où l'or est tombé. Un homme se déshabille à la proue." },
    ],
    choices: [
      { label: "Leur faire le signe des Taiseurs, la paume ouverte, le pouce replié", fx: { fac: { taiseurs: 5 } }, test: { dom: "social", diff: -10, label: "Imposer le silence", help: [LIS, GIL, { if: { has: "basse:taiseurs" }, v: 15 }] },
        win: { to: "VF_si_greve" }, lose: { to: "VF_si_plongeur" } },
      { label: "Dire à ses hommes que Riwal compte les noyer avec toi", hide: { not: { voile: "vf_si_riwal" } }, fx: { ep: ["perso", 1000] }, to: "VF_si_greve" },
      { label: "Sauter dans leur barque, la lame à la main", who: "salome", fight: { title: "Au pied de la tour", enemies: [{ id: "ecumeur", n: 3 }],
        win: { to: "VF_si_greve" }, lose: { to: "VF_si_plongeur" },
        flee: { label: "Les laisser plonger", dom: "discretion", diff: 0, to: "VF_si_plongeur" } } },
      { label: "Les laisser plonger", to: "VF_si_plongeur" },
    ] },

  VF_si_plongeur: { act: "V", title: "Celui qui a plongé", place: "sorne",
    text: [
      "Un homme plonge. Il entre dans l'eau verte la tête la première, et ses pieds disparaissent. Les autres le regardent faire, puis regardent l'eau, et restent sur leurs bancs.",
      "Il ne remonte pas. Vous l'attendez jusqu'à ce que le courant fasse tourner les barques autour de la tour. Au moment de partir, tu crois voir sa tête, au loin, sur l'eau. C'est une bouée de liège.",
      { with: "salome", text: "Salomé regarde l'endroit longtemps. « On ne peut pas les empêcher, dit-elle. On peut seulement les attendre. » Elle a dit cela d'une autre, il y a trois ans." },
    ],
    fx: { flag: "vf:noye_or" },
    choices: [{ label: "Pousser la barque", to: "VF_si_greve" }] },

  VF_si_greve: { act: "V", title: "La mer se referme", place: null,
    text: [
      "À midi, vous êtes à une lieue au large. Derrière vous, la tour de la Reine est seule au-dessus de l'eau, droite et grise. Puis elle n'est plus qu'un trait, puis un point, puis la mer plate.",
      { if: { has: "basse:taiseurs" }, text: "Dans la barque des Joncs, les trois Taiseurs se lèvent ensemble. L'Aîné fait le signe vers l'endroit où la tour a disparu, puis se tourne vers toi et le refait, plus lentement." },
      { with: "tibere", text: "Tibère regarde ses mains vides. « {{oreille#vf_si_tibere|De l'or au fond de l'eau, quelle misère|Tant mieux, j'aurais tout perdu aux dés avant l'été, et Rosalie ne m'aurait jamais pardonné}} », dit-il." },
      { with: "fauvette", text: "Fauvette se penche par-dessus bord et regarde l'eau, longtemps. C'est la première fois de sa vie qu'elle sort d'un endroit plein d'or les poches vides, et elle a l'air de trouver ça intéressant." },
      "Tu {{miroir#vf_si_miroir1|as laissé l'or par fidélité au serment|as laissé l'or parce que tu as eu peur de devenir Lothaire, ou Corisande, ou Odeline, et le serment t'a servi de porte}}.",
    ],
    choices: [{ label: "Rentrer aux Joncs-Bas", big: true, to: "VF_si_joncs" }] },

  VF_si_joncs: { act: "V", title: "Le Gardien", place: "joncs",
    takes: "night",
    text: [
      "Aux Joncs-Bas, on vous attend avec des lampes. Personne ne demande ce que vous rapportez : tout le monde le sait. Les dentellières sont assises en cercle sur le ponton de Mère Ancolie, leurs coussins sur les genoux, les mains immobiles.",
      { if: { not: { has: "iit:ancolie_blessee" } }, text: "Mère Ancolie se lève quand tu montes sur le ponton. Elle te prend le visage entre ses deux mains sèches, et elle le lit, du bout des doigts, le front, les yeux, la bouche. « {{oreille#vf_si_ancolie|Tu seras le Gardien|Tu seras le Gardien, et tu le seras mieux que Gildas, parce que toi, tu sais ce que coûte un silence}} », dit-elle." },
      { if: { has: "iit:ancolie_blessee" }, text: "Mère Ancolie est couchée, depuis la tempête. On te mène à son lit. Elle te prend la main et la serre. « Le Gardien », dit-elle seulement, et elle te fait le signe dans la paume, du bout de l'index." },
      { if: { not: { present: "gildas" } }, text: "On te passe au cou le cordon de lin noir à sept nœuds, celui que Frère Gildas a rendu au Mont, et que les moines ont renvoyé par barque." },
      "Puis on te demande ce que tu feras des instruments. Le Gardien les tient, d'habitude. Ou les rend aux familles qui les ont faits.",
    ],
    choices: [
      { label: "Garder le cornet d'os, et rendre les autres", fx: { set: { vf_instruments: "cornet" }, fac: { taiseurs: 5 } }, to: "VF_si_gildas" },
      { label: "Garder les cinq, comme le Gardien doit le faire", fx: { set: { vf_instruments: "tous" } }, to: "VF_si_gildas" },
      { label: "Les rendre tous, et apprendre à entendre sans eux", fx: { set: { vf_instruments: "aucun" }, fac: { taiseurs: 10 } }, to: "VF_si_gildas" },
    ] },

  VF_si_gildas: { act: "V", title: "L'ancien Gardien", place: null,
    text: [
      { if: { has: "gildas:mort" }, text: "Tu remontes l'Orle jusqu'au Mont-Taciturne. Les moines ont gravé le nom de Frère Gildas sur la dalle des Gardiens, sous six autres noms. Au scriptorium, sa place est restée vide, sa plume posée en travers de l'écritoire. Le frère portier te remet une lettre qu'il a laissée pour toi, pliée en quatre." },
      { if: { has: "gildas:mort" }, text: "*{{loupe#vf_si_lettre_gildas|Que Dieu garde le prochain Gardien|Je n'ai pas voulu sa mort. Elle m'a frappé, je l'ai repoussée, elle est tombée. Ne va jamais parler la nuit à celui qui vendra. Va le jour, devant témoins}}.*" },
      { if: { all: [{ has: "iv:gildas_guet" }, { not: { has: "gildas:mort" } }] }, text: "Tu montes à Salvèze voir Frère Gildas à la Tour Ronde, où il attend son jugement pour la mort d'Odeline. Il est assis sur sa paillasse, il écrit. Il a demandé du papier, et on lui en donne. Il écrit, dit-il, tout ce dont il se souvient de la nuit des Lanternes, pour le juge et pour toi." },
      { if: { all: [{ has: "gildas:chasse" }, { not: { any: [{ has: "iv:gildas_guet" }, { has: "gildas:mort" }] } }] }, text: "Tu remontes l'Orle jusqu'au Mont-Taciturne pour voir Frère Gildas, que tu as chassé. Il est au scriptorium, il recopie un psautier. Il lève les yeux quand tu entres, et il pose sa plume." },
      { if: { not: { any: [{ has: "iv:gildas_guet" }, { has: "gildas:chasse" }, { has: "gildas:mort" }] } }, text: "Frère Gildas t'accompagne jusqu'au Mont-Taciturne, où il veut finir sa vie au scriptorium. Sur la route, il te parle des devoirs du Gardien, de ce qu'on a le droit de faire, et de ce qu'il a fait." },
      { if: { not: { has: "gildas:mort" } }, text: "« Je n'ai pas voulu sa mort, dit-il. Elle allait vendre. Je suis venu lui parler. Elle m'a frappé, je l'ai repoussée, elle est tombée. Tu le sais. » Il touche la cicatrice à la racine de ses cheveux. « Ne viens jamais lui parler la nuit, à celui qui vendra. Viens le jour, devant témoins, et dis-lui ce que tu sais. »" },
      "La pièce {{echo#vf_si_gildas|est calme, et sent l'encre et le parchemin|garde la voix de Gildas, jeune, le jour où il a reçu le cordon : « Je le garderai au prix de ma vie. » Puis, plus bas : « Au prix de celle des autres, s'il le faut »}}.",
    ],
    choices: [{ label: "Rentrer en ville", to: "VF_si_ville" }] },

  VF_si_ville: { act: "V", title: "La ville sans or", place: "salveze",
    text: [
      "À la Saint-Jean, la République paie ce qu'elle peut. Le Conseil vend les galères, les cloches de deux églises, les bijoux de la Monnaie. La Banque Marrel vide ses caves et vend ses créances aux Lombards, à moitié prix.",
      { if: { has: "prevot:dejoue" }, text: "Amaury de Sauveterre accepte un accord qui ne satisfait personne : la moitié de la dette en espèces, le reste en sel sur vingt ans, et le péage du port pour le duc jusqu'à paiement. Salvèze garde ses portes, ses lois et son Conseil, et le duc garde une main dans sa bourse." },
      { if: { not: { has: "prevot:dejoue" } }, text: "Le prévôt Delisle ouvre la porte des Sauniers le lendemain de la Saint-Jean, comme il l'avait promis à l'envoyé. Les bannières bleues montent sur le Beffroi. Le duc d'Aveline prend la ville sans un coup, et la gouverne par la main de Delisle." },
      "Personne, en ville, ne sait qu'un or de quatre millions dort au fond de la mer, à quinze lieues, sous une ville noyée. Toi, tu le sais. C'est ton métier, désormais, de le savoir sans le dire.",
      { if: { has: "vf:noye_or" }, text: "À la Saint-Michel, une femme de Port-Vasier vient au quai demander des nouvelles d'un homme qui a plongé au pied de la tour de la Reine. Tu lui dis l'endroit. Elle sait déjà pourquoi il a plongé." },
    ],
    choices: [{ label: "Reprendre la boutique du quai", to: "VF_si_premier" }] },

  VF_si_premier: { act: "V", title: "Celui qui vend", place: "quai",
    text: [
      "Tu as rouvert la boutique Carrus. *Choses perdues, choses retrouvées*. Les clients reviennent peu à peu, avec leurs clés, leurs bagues, leurs lettres égarées.",
      "Un matin d'automne, un apprenti brocanteur de la boutique d'en face, un garçon de dix-sept ans qui s'appelle Médéric, entre en tenant contre lui un paquet enveloppé de toile. Il l'ouvre sur ton établi : une pierre ronde, grise, veinée de vert, grande comme un pain, qui chante quand on la frappe. Une pierre chantante.",
      "« Je l'ai trouvée dans la vase du port, dit-il. {{oreille#vf_si_mederic|Je voulais savoir ce que c'est|Un homme en gants gris m'en offre cent ducats si je lui dis où je l'ai trouvée, et je voulais savoir si elle en vaut plus}}. »",
      { if: { is: { vf_instruments: "aucun" } }, text: "Tu n'as plus le cornet. Tu entends quand même, depuis l'hiver, quelque chose dans la voix des gens, une hésitation, une couture. Mère Ancolie disait que cela vient avec le temps." },
    ],
    choices: [
      { label: "Lui dire, de jour, devant sa maîtresse, ce que tu sais de cette pierre", fx: { set: { vf_premier: "parole" }, item: "vf_tr_pierre", clock: { tresors: 1 }, flag: "tresor:vf_pierre" }, to: "VF_si_apprenti" },
      { label: "La lui acheter cent cinquante ducats", if: { gold: { min: 3000 } }, why: "Il te faudrait cent cinquante ducats.", fx: { gold: -3000, set: { vf_premier: "achat" } }, to: "VF_si_apprenti" },
      { label: "La lui reprendre la nuit, dans sa chambre, sans qu'il le sache", test: { dom: "discretion", diff: -10, label: "Voler la pierre", help: [FAU] },
        win: { fx: { set: { vf_premier: "vol" } }, to: "VF_si_apprenti" }, lose: { fx: { set: { vf_premier: "pris" } }, to: "VF_si_apprenti" } },
      { label: "Lui parler de l'homme aux gants gris, avant qu'il ne te le dise", hide: { not: { voile: "vf_si_mederic" } }, fx: { set: { vf_premier: "parole" }, ep: ["perso", 1000], item: "vf_tr_pierre", clock: { tresors: 1 }, flag: "tresor:vf_pierre" }, to: "VF_si_apprenti" },
    ] },

  VF_si_apprenti: { act: "V", title: "Médéric", place: "quai",
    text: [
      { if: { is: { vf_premier: "parole" } }, text: "Tu lui dis tout, ou presque : les Taiseurs, Sorne, Odeline, l'escalier de la cave. Sa maîtresse écoute, assise, les mains jointes. Médéric pâlit. Il remballe la pierre dans sa toile et te la tend. « Je ne veux pas finir au pied d'un escalier », dit-il. Le lendemain, il revient et te demande si tu prends un apprenti." },
      { if: { is: { vf_premier: "achat" } }, text: "Il prend l'argent, compte, recompte. Il est content. Il ne saura jamais ce qu'il a vendu. Toi, tu ranges la pierre dans la cave, sur l'établi d'Odeline, et tu te demandes combien de pierres il faudra acheter, et avec quel argent." },
      { if: { is: { vf_premier: "vol" } }, text: "Tu entres par la lucarne, à trois heures du matin. La pierre est sous son lit, dans sa toile. Médéric dort, la bouche ouverte. Il cherchera sa pierre pendant des semaines. Il accusera son maître. Tu le sais en refermant la lucarne." },
      { if: { is: { vf_premier: "pris" } }, text: "Médéric se réveille au moment où tu soulèves la toile. Il te reconnaît, dans le noir, à ta voix. Il hurle. Les voisins viennent. Le lendemain, tout le quai sait que la boutique Carrus vole la nuit. La pierre, Médéric te la rend lui-même, de peur, sans un mot. Tu as gagné. Tu as perdu le quai." },
      "Le soir, tu descends à la cave. L'escalier est raide. Tu t'arrêtes sur la marche où Odeline est tombée, et tu {{miroir#vf_si_marche|y poses la main, par respect|t'y assieds, parce que tu viens de comprendre ce que Gildas a ressenti cette nuit-là, avant de frapper à la porte}}.",
    ],
    choices: [{ label: "La nuit des Lanternes revient", big: true, to: "VF_si_fin" }] },

  VF_si_fin: { act: "V", title: "Le nouveau Taiseur", place: "quai", end: true, epilogue: true, fx: END("silence"),
    text: [
      "Un an après la Grande Basse, la nuit des Lanternes revient sur Salvèze. Tu poses une lanterne sur le canal, devant la boutique, pour Odeline. Puis une deuxième, pour la reine, sans le dire à personne.",
      "Sur le quai, les gens passent et te saluent. Pour eux, tu es le chercheur ou la chercheuse de choses perdues de la boutique Carrus, qui a fait un voyage en mer l'an dernier et n'en a rien rapporté.",
      { if: { not: { is: { vf_instruments: "aucun" } } }, text: "Tu portes le cornet d'os sous ta chemise, à côté du cordon à sept nœuds. Les voix du quai tremblent, comme toujours." },
      "Une marchande de beignets te tend un cornet de papier. « {{oreille|Pour la boutique, c'est offert|Pour celle qui est morte, je lui devais trois ducats et je ne les ai jamais rendus}} », dit-elle. Un vieux batelier pose sa lanterne près de la tienne. « {{oreille|Belle nuit|Belle nuit, et je sais d'où tu reviens, j'ai vu la barque des Joncs te ramener}} », dit-il, et il te fait, très vite, le signe des marais.",
      { if: { has: "tresor:vf_pierre" }, text: "La pierre de Médéric est posée sur l'établi d'Odeline, dans sa toile. Il la regarde en passant le balai, et il la contourne." },
      { if: { is: { vf_premier: "parole" } }, text: "Médéric balaie la boutique derrière toi. Il apprend les mots à double sens depuis l'hiver. Il en rit encore, la plupart du temps." },
      { with: "lison", text: "Lison est venue des Joncs en barque. Elle s'assied sur la troisième marche. « {{oreille#vf_si_lison_fin|Je passais|Je viendrai tous les ans, et un jour je resterai, si tu me le demandes}} », dit-elle." },
      { with: "tibere", text: "Tibère a apporté du vin chaud. Il le sert dans des gobelets d'étain et n'en boit qu'un." },
      { with: "salome", text: "Salomé t'a envoyé de Port-Vasier un panier d'huîtres et un mot : *Je plonge de nouveau. Pour rien. Pour regarder.*" },
      { with: "fauvette", text: "Fauvette est assise sur le toit d'en face, les jambes dans le vide. Elle te fait signe. Elle sait le signe des Taiseurs, maintenant. Elle le fait de travers, exprès." },
      "Ta lanterne prend le courant vers la mer, vers Sorne, vers la salle noyée où la Charte attend. Tu {{miroir#vf_si_dernier|gardes le silence parce que tu l'as juré|gardes le silence parce qu'il te rend, enfin, la paix que tu as perdue le soir où tu as claqué la porte de la boutique, et tu sais que cette raison est trop petite pour un serment, et tu le gardes quand même}}.",
    ] },
});

// ==================================================================== VF_fortune: the gold, another country, another tongue
var SUD = { is: { vf_pays: "sud" } }, EST = { is: { vf_pays: "est" } };
Object.assign(P, {
  VF_fortune: { act: "V", title: "L'or à bord", place: "sorne",
    fx: { ep: ["seance", 2000] },
    text: [
      "Au pied de la tour de la Reine, tu fais descendre l'or dans la barque. Tu donnes les ordres d'une voix nette, nouvelle pour toi. On t'obéit.",
      { if: PLEIN, text: "Les trois coffres de la reine descendent au bout de la corde du treuil. Au dernier, la barque s'enfonce d'une main." },
      { if: PARTIE, text: "Les besaces s'empilent au fond de la barque, sous une bâche. Une part seulement de l'or de la reine, assez pour une vie, ou pour trois." },
      { if: PLOMB, text: "Une des besaces s'est ouverte en tombant. Les pièces roulent sur les planches avec un bruit sourd, trop sourd. Tu en ramasses une. Tu la mords. Elle cède sous la dent. Tu la remets dans la besace sans rien dire." },
      { if: CHARTE, text: "La Charte est contre ta poitrine, dans son étui. Ce que tu en feras, tu l'ignores encore. Tu sais seulement que tu la garderas pour toi." },
      "Puis tu te retournes vers les autres, et tu leur dis que tu ne rentres pas à Salvèze.",
      "Tu {{miroir#vf_fo_raison|pars parce que la ville ne mérite pas cet or|pars parce que, depuis la mort d'Odeline, tu as peur tous les jours, et que l'or est la seule chose que tu as trouvée qui fasse taire la peur}}.",
    ],
    choices: [{ label: "Regarder qui reste, et qui vient", big: true, to: "VF_fo_adieux" }] },

  VF_fo_adieux: { act: "V", title: "Les adieux", place: "sorne",
    text: [
      { with: "lison", text: "Lison te regarde un long moment. « {{oreille#vf_fo_lison|Bon vent, alors|Je serais allée au bout du monde avec toi pour la Charte, et je ne fais pas un pas pour l'or}} », dit-elle. Elle saute dans la barque des Joncs et pousse sur sa perche sans se retourner." },
      { with: "salome", text: "Salomé croise les bras. « Je ramène mes gens à Port-Vasier, dit-elle. Pour le reste, tu trouveras bien quelqu'un qui sait tenir une barre. » Elle crache dans l'eau, entre vos deux barques, et c'est tout." },
      { with: "gildas", text: "Frère Gildas fait le signe de croix sur toi, sur la barque, sur l'or. « Je prierai pour que tu dormes, dit-il. C'est ce qui est le plus difficile, ensuite. » Il le sait mieux que personne." },
      { with: "tibere", text: "Tibère regarde l'or, puis la ville, au nord, puis encore l'or. « {{oreille#vf_fo_tibere|Je viens, tu auras besoin d'un homme qui sait se battre|Je viens, et j'enverrai de l'argent à Rosalie chaque mois, et elle saura d'où il vient, et elle le prendra quand même}} », dit-il, et il monte à bord." },
      { with: "fauvette", text: "Fauvette est déjà assise sur un coffre. « J'ai toujours voulu voir un pays où personne ne sait que je suis une voleuse », dit-elle. Puis, plus bas : « {{oreille#vf_fo_fauvette|Et puis quelqu'un doit te surveiller|Et puis je n'ai que toi, et je ne veux pas que tu partes sans moi}}. »" },
      { without: "any", text: "Il n'y a que les gens de la barque. Tu leur offres le passage, ou leur part. La plupart prennent leur part et descendent dans l'autre barque. Deux restent : un vieux marin qui n'a plus de famille, et son neveu." },
    ],
    choices: [
      { label: "Laisser une part de l'or à ceux qui restent", fx: { flag: "vf:part_donnee", fac: { hautes: 5, ecumeurs: 5 } }, to: "VF_fo_cap" },
      { label: "Tout garder", fx: { fac: { ecumeurs: -10 } }, to: "VF_fo_cap" },
    ] },

  VF_fo_cap: { act: "V", title: "Le cap", place: null,
    text: [
      "Au large, la mer est vide et la côte n'est plus qu'une ligne. Tu déplies sur le banc une carte de marin, de celles qu'on vend au port aux Sauniers pour un ducat, et tu cherches un pays.",
      "Au sud, à neuf jours de voile, il y a Bellarade, une ville blanche aux toits plats, où l'on parle une langue chantée et où l'on vend tout ce qui se vend, sans demander d'où il vient. À l'est, au-delà du détroit, il y a l'Ostrévie, des forêts, des fleuves larges, et la ville de Tarvène, où les banquiers d'Ostrévie prêtent aux rois et ignorent le nom de Marrel.",
      { if: { has: "ivm:part_ecumeurs" }, text: "Derrière vous, deux voiles brunes ont paru à l'horizon. Riwal attendait sa part à Port-Vasier. Il est venu la chercher." },
    ],
    choices: [
      { label: "Le sud, vers Bellarade", fx: { set: { vf_pays: "sud" } }, to: "VF_fo_poursuite" },
      { label: "L'est, vers Tarvène", fx: { set: { vf_pays: "est" } }, to: "VF_fo_poursuite" },
    ] },

  VF_fo_poursuite: { act: "V", title: "La poursuite", place: null,
    text: [
      { if: { has: "ivm:part_ecumeurs" }, text: "Les voiles brunes de Riwal grossissent toute la journée. Au soir, elles sont à une lieue.", else: "Au deuxième jour, une galère noire paraît sur l'arrière, sous les besants d'or de la Banque Marrel. Corisande a des yeux partout, et des rameurs reposés." },
      "Le vent faiblit avec le soleil. Ta barque est lourde de son or. La leur est vide, et longue, et elle a deux fois plus de rames.",
      "Le capitaine des poursuivants te hèle au porte-voix, en fin de journée. « {{oreille#vf_fo_poursuivant|Rendez l'or, et vous aurez la vie sauve|Rendez l'or, et on vous noie quand même, pour qu'il n'y ait pas de témoin}} ! » crie-t-il.",
    ],
    choices: [
      { label: "Jeter une besace par-dessus bord, devant eux, et filer pendant qu'ils plongent", hide: { not: { voile: "vf_fo_poursuivant" } }, fx: { flag: "vf:besace_jetee", ep: ["perso", 1000] }, to: "VF_fo_escale" },
      { label: "Attendre la nuit et éteindre les fanaux", test: { dom: "nature", diff: -20, label: "Disparaître dans la nuit", help: [SAL, TIB, { if: { item: "ivm_astrolabe" }, v: 10 }] },
        win: { to: "VF_fo_escale" }, lose: { to: "VF_fo_perte" } },
      { label: "Les laisser aborder, et les recevoir", fight: { title: "La poursuite", enemies: [{ id: "ecumeur", n: 3 }, { id: "spadassin", n: 1 }],
        win: { to: "VF_fo_escale" }, lose: { to: "VF_fo_perte" },
        flee: { label: "Couper la corde du grappin", dom: "combat", diff: -10, to: "VF_fo_perte" } } },
    ] },

  VF_fo_perte: { act: "V", title: "La moitié", place: null,
    text: [
      "Ils vous rejoignent à l'aube. Il y a des cris, des coups, un homme qui tombe à l'eau et qu'on ne repêche pas. Quand ils repartent, ils emportent la moitié de l'or. Ils vous laissent la barque, l'autre moitié, et la vie. Ils ont eu peur, au dernier moment, ou ils étaient trop chargés pour vous prendre le reste.",
      { with: "tibere", text: "Tibère a une estafilade au bras. Il la regarde en riant. « La moitié d'un trésor de reine, dit-il. C'est encore plus que ce que j'ai jamais perdu aux dés. »" },
      { with: "fauvette", text: "Fauvette sort de sous la bâche, très pâle. Elle a quatre pièces d'or dans chaque poing. « Ils n'ont pas compté », dit-elle." },
    ],
    fx: { flag: "vf:or_moitie" },
    choices: [{ label: "Continuer la route", to: "VF_fo_escale" }] },

  VF_fo_escale: { act: "V", title: "L'arrivée", place: null,
    text: [
      { if: SUD, text: "Bellarade sort de la mer au neuvième jour, blanche et plate, avec ses toits en terrasse où sèche du linge de toutes les couleurs. Le port sent l'huile chaude, le poisson grillé, la poix. Les gens crient des mots que tu ne comprends pas, sur un air qui monte et qui descend." },
      { if: EST, text: "Tarvène se découvre au fond d'un estuaire gris, sous une pluie fine, avec ses clochers verts en bulbe et ses quais de bois. Le port sent la résine et le hareng. Les gens parlent bas, avec des sons au fond de la gorge, et tu ne comprends rien." },
      "Tu portes le cornet d'os à ton oreille, par habitude, pour écouter un débardeur qui t'interpelle. Les mots tremblent. Et sous les mots, tu entends ce qu'il pense, clair, dans ta propre langue. Le cornet ne connaît pas les frontières.",
      "« {{oreille#vf_fo_debardeur|Bienvenue, voyageur, je porte vos bagages|Celui-là a du lourd dans ses caisses, il faut prévenir le changeur du port avant qu'il trouve un honnête homme}} », dit le débardeur.",
    ],
    choices: [
      { label: "Éviter le changeur du port et chercher un honnête homme", hide: { not: { voile: "vf_fo_debardeur" } }, fx: { flag: "vf:honnete", ep: ["perso", 800] }, to: "VF_fo_changeur" },
      { label: "Suivre le débardeur jusqu'au changeur du port", to: "VF_fo_changeur" },
    ] },

  VF_fo_changeur: { act: "V", title: "Le changeur", place: null,
    text: [
      { if: { has: "vf:honnete" }, text: "Tu trouves, dans une ruelle derrière le marché aux épices, une vieille femme qui change l'or des pèlerins depuis quarante ans. Elle pèse chaque pièce deux fois, devant toi, sur une balance ancienne. Elle t'offre un prix juste, et elle te prévient, par gestes, de ne pas montrer ta bourse sur le port.", else: "Le changeur du port est un homme rond, jovial, couvert de bagues. Il te fait asseoir, te sert du vin, et pose ton or sur sa balance." },
      { if: { not: { has: "vf:honnete" } }, text: "Sa balance {{pie#vf_fo_balance|est une belle balance de cuivre, aux plateaux luisants|a un fléau creux où roule une bille de plomb, qu'il fait glisser du petit doigt : il te volera un quart à chaque pesée}}." },
      { if: { has: "vt:or_dette" }, text: "Le changeur passe le pouce sur la ligne frappée au poinçon, sur la tranche d'un lingot, sans la lire. Toi, tu la lis encore." },
      { if: { all: [{ has: "vt:or_trie" }, { not: PLOMB }] }, text: "Ton or est franc, lingot après lingot : tu l'as trié toi-même au fond de Sorne. Le changeur le touche à la pierre de touche, et il lève les sourcils." },
      { if: PLOMB, text: "Une partie de ton or est du plomb sous une feuille d'or. Tu le sais, maintenant. Tu le fais peser avec le reste, et tu regardes le changeur, et tu te demandes lequel de vous deux vole l'autre." },
    ],
    choices: [
      { label: "Arrêter la bille du doigt, et sourire au changeur", hide: { any: [{ not: { voile: "vf_fo_balance" } }, { has: "vf:honnete" }] }, fx: { gold: 2000, ep: ["perso", 800] }, to: "VF_fo_maison" },
      { label: "Accepter le prix", fx: { gold: 10000 }, to: "VF_fo_maison" },
    ] },

  VF_fo_maison: { act: "V", title: "La maison", place: null,
    text: [
      { if: SUD, text: "Tu achètes une maison sur la colline, au-dessus du port de Bellarade, avec une terrasse, un figuier et une citerne. Le premier été, tu apprends cent mots de la langue chantée. Le deuxième, tu rêves dedans." },
      { if: EST, text: "Tu achètes une maison de pierre au bord du fleuve, à Tarvène, avec un poêle de faïence verte qui chauffe trois pièces. Le premier hiver, tu apprends cent mots de la langue de gorge. Le deuxième, tu rêves dedans." },
      { if: { has: "vf:or_moitie" }, text: "Tu as la moitié de l'or. C'est encore une fortune. Tu le dis souvent, à voix haute, pour t'en convaincre." },
      { if: { has: "vf:besace_jetee" }, text: "Il te manque une besace, celle que tu as jetée aux poursuivants. Certains soirs, tu la comptes encore avec le reste." },
      { with: "tibere", text: "Tibère s'est trouvé une taverne à son goût, dans la ville basse, où l'on joue aux dés dans une langue qu'il ne parle pas. Il perd moins qu'avant. Les annonces lui échappent, et il dit que c'est pour ça." },
      { with: "fauvette", text: "Fauvette parle la langue du pays avant toi, avec l'accent des docks. Elle a des amis partout, et des clés de partout." },
      { if: { has: "vt:avis_fauvette" }, with: "fauvette", text: "Le soir, sous la lampe, tu apprends à lire à Fauvette, dans ta langue et dans celle du pays. Elle a voulu commencer par le mot *terre*." },
      "On t'appelle par ton nom, ici, mais mal prononcé. Au bout d'un an, tu te retournes quand on le prononce comme eux.",
    ],
    choices: [{ label: "Un an plus tard, un navire de Salvèze entre au port", to: "VF_fo_nouvelles" }] },

  VF_fo_nouvelles: { act: "V", title: "Les nouvelles", place: null,
    text: [
      "Un gabarier de Salvèze vient décharger du sel sur le quai. Tu reconnais l'accent avant le visage. Tu lui offres à boire, et tu lui demandes des nouvelles, comme un étranger qui a entendu parler de la ville.",
      { if: { has: "prevot:dejoue" }, text: "« Salvèze ? Elle tient, dit-il. Mal, mais elle tient. La République n'a pas pu payer le duc à la Saint-Jean. On a vendu les galères, les cloches, la moitié du sel des Hautes-Eaux pour vingt ans. La Banque Marrel a fait faillite à l'automne. Le pain coûte deux liards de plus. On vit. »" },
      { if: { not: { has: "prevot:dejoue" } }, text: "« Salvèze ? Elle est au duc, maintenant, dit-il. Le prévôt a ouvert la porte des Sauniers le lendemain de la Saint-Jean. Les bannières bleues sont sur le Beffroi. On paie l'impôt à Aveline. On vit. »" },
      "Puis il ajoute, en baissant la voix : « Il paraît qu'un chercheur du quai des Lanternes a trouvé le trésor de la Muette, et qu'il est parti avec. {{oreille#vf_fo_gabarier|Moi, je l'aurais fait aussi|S'il revient un jour, on le pendra au pont des Muets, et j'y serai, et j'apporterai mon fils}}. »",
    ],
    choices: [
      { label: "Lire la lettre qu'il te remet, et qui t'attendait au port depuis un mois", to: "VF_fo_lettre" },
    ] },

  VF_fo_lettre: { act: "V", title: "La lettre", place: null,
    text: [
      "La lettre porte ton nom, ton vrai nom, écrit d'une main que tu connais. Elle a voyagé de port en port pendant des mois, de gabarier en gabarier, jusqu'à toi.",
      { if: { has: "lison:rencontre" }, text: "*{{loupe#vf_fo_lettre|Je t'écris pour te dire que tout va bien aux Joncs, et que tu n'as pas à t'en faire|L'intendant des Fourcaud a doublé le cens. On a démonté six maisons. Ma grand-mère ne dit plus ton nom. Moi je le dis, le soir, sur l'eau, et ça ne sert à rien}}.*\n\n*L.*" },
      { if: { not: { has: "lison:rencontre" } }, text: "*{{loupe#vf_fo_lettre_quai|Je t'écris pour te dire que tout va bien au quai, et que tu n'as pas à t'en faire|On a vendu la boutique d'Odeline aux enchères. C'est un marchand de la Banque qui l'a achetée. Il a fait murer l'escalier de la cave}}.*" },
    ],
    choices: [
      { label: "Ouvrir le coffre où dort la Charte", hide: { not: CHARTE }, to: "VF_fo_charte" },
      { label: "Envoyer de l'argent, sans un mot, par le même gabarier", fx: { flag: "vf:argent_envoye", gold: -4000, fac: { hautes: 5 } }, to: "VF_fo_annees" },
      { label: "Ranger la lettre dans un tiroir", to: "VF_fo_annees" },
    ] },

  VF_fo_charte: { act: "V", title: "Le coffre", place: null,
    text: [
      "La Charte est dans un coffre de cèdre, sous ton lit, dans son étui de cuir ciré. Tu l'en sors pour la première fois depuis Sorne. La cire verte a tenu. L'écriture de la reine est aussi nette qu'au premier jour.",
      "Tu la relis, seul{e}, à la lampe, dans une langue que plus personne ne parle autour de toi. *{{loupe#vf_fo_charte|Nous, Ysaure, reine du delta, voulons que les terres gagnées sur la mer appartiennent à ceux qui les ont gagnées|Et celui qui la gardera pour lui seul, qu'il sache qu'il garde une prison, et qu'il en a la clé}}.*",
    ],
    choices: [
      { label: "La renvoyer aux Joncs-Bas, par le gabarier, sans un mot", fx: { flag: "vf:charte_renvoyee", fac: { taiseurs: 10, hautes: 10 } }, to: "VF_fo_annees" },
      { label: "La remettre dans le coffre", fx: { flag: "vf:charte_gardee" }, to: "VF_fo_annees" },
      { label: "La brûler dans le poêle", fx: { flag: "vf:charte_brulee" }, to: "VF_fo_annees" },
    ] },

  VF_fo_annees: { act: "V", title: "Les années", place: null,
    text: [
      "Les années passent. Tu deviens quelqu'un, dans ta nouvelle ville : une personne riche, discrète, qui prête sans usure aux pêcheurs et qui garde le silence sur son pays. On t'invite. On t'envie. On te croit veuf ou veuve, à cause de ton air.",
      { if: { has: "vf:charte_renvoyee" }, text: "Un été, un gabarier te rapporte que les gens des Joncs-Bas ont reçu un paquet de la mer. Ils l'ont caché sous un plancher. Ils ont envoyé une barque à la chapelle de Port-Vasier, pour faire dire une messe pour un vivant." },
      { if: { has: "vf:charte_brulee" }, text: "Il t'arrive de rêver de la cire verte qui fond et prend feu avec une flamme bleue. Tu te réveilles toujours au même moment, la main tendue vers le poêle." },
      { if: { has: "vf:argent_envoye" }, text: "Chaque printemps, le gabarier de Salvèze repart de ton port avec une bourse cousue dans sa veste. Une fois, il te rapporte un mot sans signature : *Reçu. Le toit tient.*" },
      "Tu ranges le cornet d'os dans un tiroir. Tu le ressors. Tu le ranges. Dans ce pays, les gens qui t'aiment pensent la même chose que ce qu'ils disent, presque toujours, et cela te fait peur.",
    ],
    choices: [
      { label: "Revenir une seule nuit à Salvèze, sans dire ton nom", fx: { flag: "vf:retour_nuit" }, to: "VF_fo_retour" },
      { label: "Vieillir", big: true, to: "VF_fo_fin" },
    ] },

  VF_fo_retour: { act: "V", title: "Une nuit à Salvèze", place: "quai",
    takes: "night",
    text: [
      "Tu reviens à Salvèze sur un navire marchand, la nuit des Lanternes, dix ans après la Grande Basse. Tu as un manteau du pays, une barbe ou des rides, un accent qui fait se retourner les douaniers. Personne ne te reconnaît.",
      "Le quai des Lanternes {{echo#vf_fo_quai|est plein de monde et de flammes sur l'eau|garde, sous la foule, ta propre voix, la nuit de la mort d'Odeline : « Tu mourras seule avec tes secrets », et le bruit de la porte qui claque}}.",
      "Tu achètes une lanterne de papier à une gamine qui te rend la monnaie dans ta langue, en articulant, comme à un étranger. Tu la poses sur l'eau devant la boutique Carrus, qui vend maintenant des chapeaux. Tu repars avec la marée du matin.",
    ],
    choices: [{ label: "Rentrer chez toi, de l'autre côté de la mer", big: true, to: "VF_fo_fin" }] },

  VF_fo_fin: { act: "V", title: "La fortune", place: null, end: true, epilogue: true, fx: END("fortune"),
    text: [
      { if: SUD, text: "Tu vieillis sur ta terrasse de Bellarade, sous le figuier, face à la mer, en parlant une langue chantée qui est devenue la tienne. Les enfants du quartier t'appellent d'un nom qui veut dire *l'étranger du nord*." },
      { if: EST, text: "Tu vieillis au bord du fleuve de Tarvène, près du poêle de faïence verte, en parlant une langue de gorge qui est devenue la tienne. Les enfants du quartier t'appellent d'un nom qui veut dire *celui qui vient de la mer*." },
      { if: { has: "vf:charte_gardee" }, text: "La Charte dort toujours dans le coffre de cèdre, sous ton lit. Tu as écrit sur l'étui, d'une main qui tremble un peu, l'adresse des Joncs-Bas, pour après." },
      { if: { has: "vf:retour_nuit" }, text: "Sur ta table, dans une soucoupe, tu gardes les liards que la gamine du quai des Lanternes t'a rendus, la nuit de ton retour. Ils y sont encore." },
      "Un soir, un jeune homme frappe à ta porte. Il est chercheur de choses perdues, dit-il, dans le port d'ici, et il a entendu parler de toi. Il voudrait apprendre le métier. Il a les yeux de quelqu'un qui a faim.",
      { if: CORNET, text: "Tu prends le cornet d'os dans le tiroir et tu le portes à ton oreille. « {{oreille#vf_fo_jeune|Je veux apprendre à trouver les choses|Je veux savoir où tu as caché ton or, et je ne partirai pas avant}} », dit-il dans sa langue, que le cornet te rend dans la tienne." },
      { with: "tibere", text: "Tibère est mort l'hiver dernier, dans son lit, une chope à portée de main. Il a laissé une lettre pour Rosalie que tu as envoyée par le premier bateau. « {{oreille|Tout ça, c'était pour toi|Je n'ai jamais rien fait pour toi, que partir}} », disait-il souvent, à la fin." },
      { with: "fauvette", text: "Fauvette vit à trois rues d'ici. Elle a épousé un capitaine de port, elle a trois enfants qui lui volent ses bagues. Elle vient le dimanche. « {{oreille#vf_fo_fauvette_fin|Tu as bien fait de partir|Tu as bien fait de m'emmener, et tu n'aurais pas dû partir, les deux sont vrais}} », dit-elle." },
      { without: "any", text: "Tu n'as personne pour en parler. Le vieux marin et son neveu sont repartis vers le nord il y a des années. Le neveu t'écrit, parfois, des lettres mal orthographiées, pleines de bateaux." },
      "Tu fais entrer le jeune homme. Tu lui sers à boire. Tu commences à lui apprendre ce qu'Odeline t'a appris : où les gens posent les choses, et pourquoi ils les oublient. Tu {{miroir#vf_fo_dernier|lui donnes ce que tu sais, comme Odeline l'a fait pour toi|lui donnes ce que tu sais pour que quelqu'un, une fois, te pose les questions qu'on t'aurait posées à Salvèze, et tu attends le jour où il te demandera d'où vient ton or, et tu ne sais pas encore ce que tu lui répondras}}.",
    ] },
});

